window.LESSONS=window.LESSONS||{};window.LESSONS["assembly-language/chapter-8"]={"meta": {"key": "assembly-language/chapter-8", "course": "assembly-language", "courseName": "組合語言", "courseTag": "COMPUTER SYSTEMS · x86", "courseDescription": "從資料、位址與堆疊，理解程序如何運作。", "unit": "chapter-8", "label": "第八章", "number": 8, "title": "進階程序與堆疊框架", "english": "Advanced Procedures", "pdf": "raw/pdfs/1151 ch8.pdf", "assetBase": "website/assets/assembly-ch8/", "sourceWiki": "wiki/sources/src-20261105-assembly-ch8.md", "sourceId": "src-20261105-assembly-ch8", "externalSourceId": "web-20261105-microsoft-masm-procedures", "downloads": "website/downloads/assembly-chapter-8", "script": "website/lessons/assembly-chapter-8.js", "groups": [["程序介面", 1, 8], ["堆疊與參數", 9, 20], ["區域變數與框架", 21, 30], ["MASM 呼叫與定址", 31, 40], ["程式追蹤", 41, 45], ["多模組", 46, 49], ["作業與比對", 50, 51]], "diagrams": "assembly", "expectedPages": 51, "references": [{"title": "組合語言第八章｜原始 PDF", "url": "raw/pdfs/1151 ch8.pdf", "detail": "主要來源 · PDF pp. 1–51 · Kip R. Irvine · 2015 版投影片與課堂增補混編"}, {"title": "Microsoft Learn｜INVOKE", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/invoke?view=msvc-170", "detail": "2026-11-05 有限查證：正文與語法；32-bit MASM 的適用範圍"}, {"title": "Microsoft Learn｜PROC", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/proc?view=msvc-170", "detail": "2026-11-05 有限查證：語法與 Remarks；含 x64 FRAME，未使用其完整例程"}, {"title": "Microsoft Learn｜PROTO", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/proto?view=msvc-170", "detail": "2026-11-05 有限查證：定義、語法與參數；原型與語言慣例"}, {"title": "Microsoft Learn｜LOCAL", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/local-masm?view=msvc-170", "detail": "2026-11-05 有限查證：程序內 LOCAL 的語法與生命期"}, {"title": "Microsoft Learn｜OPTION", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/option-masm?view=msvc-170", "detail": "2026-11-05 有限查證：選項列表中的 PROC／PROLOGUE／EPILOGUE"}, {"title": "Microsoft Learn｜PUBLIC", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/public-masm?view=msvc-170", "detail": "2026-11-05 有限查證：定義與語法；跨模組可見性"}, {"title": "Microsoft Learn｜__stdcall", "url": "https://learn.microsoft.com/en-us/cpp/cpp/stdcall?view=msvc-170", "detail": "僅正文及 Remarks 表：右至左、callee 清引數；未匯入範例"}, {"title": "Microsoft Learn｜x64 calling convention", "url": "https://learn.microsoft.com/en-us/cpp/build/x64-calling-convention?view=msvc-170", "detail": "僅 defaults、alignment、parameter passing：釐清本章與 Windows x64 範圍；其餘未使用"}], "referenceNote": "51 頁完整對應；保留原教材與遮答案頁，勘誤及適用條件另列於來源與 notes。程式碼未經 MASM／Irvine32 原生組譯執行，模型驗證與網站驗收分別記錄。外部文獻需連網；使用範圍見 Wiki。"}, "pages": [{"page": 1, "title": "第八章：進階程序", "translation": "《x86 處理器組合語言》第七版、全球版。作者 Kip R. Irvine；第八章：進階程序（Advanced Procedures）。投影片由作者製作，Pearson Education © 2015。\n\n原頁授權聲明：可為個人或課堂用途修改、複製本投影片，但須保留版權聲明、作者姓名與標題。原檔完整保留此聲明；網站另用自製學習封面。", "explanation": "本章要把「CALL 到某處，RET 回來」擴充成可重用的程序介面：呼叫者如何交付資料、被呼叫者如何找參數及區域變數、最後如何恢復堆疊。\n\n閱讀先備是暫存器、MOV、PUSH／POP、CALL／RET 與基本定址。本教材主要採 32 位元 MASM、EBP 堆疊框架與類 stdcall 的例子；它不是所有 x86／C++／x64 程式的通用配置。", "supplement": "", "printedPage": null}, {"page": 2, "title": "PROC：具名參數與型別", "translation": "PROC 偽指令宣告程序，並可附上具名參數串列。基本表示為：\n```asm\nlabel PROC paramList\n; 每個參數：paramName:type\n```\nparamList 內參數以逗號分隔。type 可為 BYTE、SBYTE、WORD 等標準組合語言型別，也可為指向這些型別的指標。原頁旁註「不適用於 64-bit 模式」。", "explanation": "參數名稱是組譯器提供的符號，不是新增 CPU 暫存器。例如 val1:DWORD 告訴 MASM 此參數按 32 位元資料使用；p:PTR DWORD 表示傳入指標，指向 DWORD 資料，而不是直接傳入那個 DWORD。\n\n帶參數的實際常用寫法是下一頁的「程序名 PROC, 參數串列」；本頁是概略語法。PROC 在組譯時建立程序結構及符號，CPU 執行的是它生成的指令。", "supplement": "範圍釐清：本頁的 64-bit 警語應限於這套 32 位元具名堆疊參數用法，不能推成「ml64 完全沒有 PROC」。官方 PROC 文件另有 x64 的 FRAME 語法；見本單元 Microsoft 查證來源。", "printedPage": 2}, {"page": 3, "title": "PROC：參數換行格式", "translation": "參數串列可另起一行或多行，PROC 後須有逗號：\n```asm\nlabel PROC,\n    paramList\n```\n可在同一行寫多個參數：\n```asm\nparam1:type1, param2:type2, ..., paramN:typeN\n```\n也可每行一個；除最後一個參數外，各項之間仍須有逗號。原圖箭頭特別指出 PROC 後的逗號。", "explanation": "換行只是排版，逗號才負責分隔。先看程序名稱，再列「名稱:型別」；如果第二行仍有下一個參數，上一行末尾要保留逗號。\n\n這個規則在 PDF pp. 41–42 的 FillArray 將再次用到：原碼少一個分隔逗號，不應因換行而以為可以省略。", "supplement": "", "printedPage": 3}, {"page": 4, "title": "AddTwo：兩整數相加", "translation": "AddTwo 接收兩個整數，以 EAX 傳回和：\n```asm\nAddTwo PROC,\n    val1:DWORD, val2:DWORD\n    mov eax,val1\n    add eax,val2\n    ret\nAddTwo ENDP\n```", "explanation": "輸入是 val1 與 val2 兩個 DWORD；輸出是 EAX。MOV 先把 val1 的值複製到 EAX，ADD 再將 val2 加入。例如輸入 5 與 6，EAX 依序為 5、11。\n\n這裡沒手寫 PUSH EBP，不代表沒有框架；在本章設定下，MASM 可依 PROC 參數產生進入／退出程式碼。PDF p. 39 會展示展開形式。DWORD 加法保留低 32 位元；若要判斷有號／無號溢位，還須檢查旗標，原例未做。", "supplement": "", "printedPage": 4}, {"page": 5, "title": "INVOKE：帶引數呼叫", "translation": "32 位元模式的 INVOKE 偽指令可取代手動準備多個引數再 CALL 的寫法。\n```asm\nINVOKE procedureName [, argumentList]\n```\n引數串列可省略，項目以逗號分隔。引數可以是立即值與整數運算式、變數名稱、位址及 ADDR 運算式、暫存器名稱。", "explanation": "argument 是呼叫端實際提供的資料，parameter 是程序端接收它的名稱。例如 INVOKE AddTwo,5,6 中，5、6 是引數，val1、val2 是參數。\n\nINVOKE 是組譯時的便利語法；MASM 依原型及呼叫慣例安排引數並生成 CALL。它不是 CPU 另有一條能理解任意型別的 INVOKE 指令，亦不會自行替你判斷指標指向的記憶體是否有效。", "supplement": "", "printedPage": 5}, {"page": 6, "title": "PROTO：先宣告介面", "translation": "PROTO 建立程序原型：\n```asm\nlabel PROTO paramList\n```\n原頁說明：64 位元模式不允許這裡的參數串列；每個以 INVOKE 呼叫的程序都要有原型，完整的程序定義也可充當自己的原型。", "explanation": "原型告訴 MASM 名稱、參數型別與順序，讓呼叫點不必等到程序實作才知道如何傳參數。只有 PROTO 並不產生函式主體，也不能代替連結時的實作。\n\n如果完整 PROC 定義在呼叫點之前，組譯器已有介面資訊；如果定義在後面或另一個模組，先寫 PROTO。原型與實作必須一致，否則呼叫端與被呼叫端可能對堆疊內容有不同解讀。", "supplement": "", "printedPage": 6}, {"page": 7, "title": "PROTO、INVOKE 與實作的位置", "translation": "典型配置：程序原型放在程式前方，INVOKE 放在程式碼區段，程序實作稍後出現。\n```asm\nMySub PROTO             ; 程序原型\n.code\nINVOKE MySub            ; 呼叫\nMySub PROC              ; 實作\n    ; ...\nMySub ENDP\n```", "explanation": "由上到下分清三件事：PROTO 宣告「有這個介面」，INVOKE 是執行時要發生的呼叫，PROC...ENDP 是被執行的主體。此例沒有參數，所以原型與呼叫都不附引數。\n\n這張只是位置示意，省略主程序入口、正常結束及完整主體。若把片段逐字串成可執行流程，不能讓呼叫返回後又直接落入程序本體；完整程式要安排主程序的結束或跳轉。", "supplement": "", "printedPage": 7}, {"page": 8, "title": "ArraySum 的指標與長度原型", "translation": "ArraySum 原型列出兩個參數：\n```asm\nArraySum PROTO,\n    ptrArray:PTR DWORD,  ; 指向陣列\n    szArray:DWORD        ; 陣列大小\n```", "explanation": "ptrArray 是陣列第一個元素的位址；szArray 提供元素數，因為只有指標無法知道陣列長度。PTR DWORD 指出每個元素按 4 bytes 解讀，但指標本身在本章 flat 32 位元模型也是 4 bytes。\n\n若三個 DWORD 位於 A、A+4、A+8，呼叫者傳 A 與 3；實作才知道要讀三次，每次位址加 4。這張只宣告介面，沒有相加流程或實際回傳值的程式。", "supplement": "", "printedPage": 8}, {"page": 9, "title": "堆疊框架的建立", "translation": "堆疊框架（stack frame）也稱活動紀錄（activation record），是為一次程序呼叫保留的堆疊區域，包含返回位址、傳入參數、保存的暫存器與區域變數。\n\n建立步驟：呼叫者先將引數壓入堆疊並呼叫程序；被呼叫者將 EBP 壓入堆疊，再令 EBP=ESP；需要區域變數時，從 ESP 減去固定大小以保留空間。", "explanation": "堆疊向較低位址成長，所以 PUSH 會讓 ESP 變小。EBP 固定作為這次呼叫的定位基準，ESP 則可因 PUSH 或區域配置繼續移動。\n\n本章典型框架內，[EBP] 是舊 EBP，[EBP+4] 是返回位址，[EBP+8] 起是參數，負偏移處放區域變數。這個配置由「32 位元近呼叫＋先存 EBP」推得；若省略 frame pointer 或換呼叫慣例，不能直接套用。", "supplement": "", "printedPage": 10}, {"page": 10, "title": "堆疊參數與暫存器參數", "translation": "原頁認為堆疊參數較方便，並比較兩種呼叫方式，問哪種較容易：\n```asm\n; 暫存器介面\npushad\nmov esi,OFFSET array\nmov ecx,LENGTHOF array\nmov ebx,TYPE array\ncall DumpMem\npopad\n\n; 假設採堆疊介面的版本\npush TYPE array\npush LENGTHOF array\npush OFFSET array\ncall DumpMem\n```", "explanation": "兩段要交付的資訊相同：陣列起始位址、元素數及每個元素的 bytes 數。左段先保存通用暫存器，再設定 ESI／ECX／EBX；右段把三筆資料壓入堆疊，由程序依位置讀取。\n\n右段比較簡潔的前提，是被呼叫程序真的採這種堆疊介面，並且雙方約定誰清除 12 bytes 的引數。PUSHAD／POPAD 也會保存及還原 EAX，所以不能把這個模板直接套在以 EAX 回傳結果的呼叫上。", "supplement": "介面警告：這是「兩種可能介面」的比較，不代表只改呼叫端就能改用原本的同名函式。本教材未取得／執行所用 Irvine32 函式庫的對應實作，不把右段聲稱為可直接替換的已測試程式。", "printedPage": 11}, {"page": 11, "title": "傳值呼叫的步驟", "translation": "傳值（passing by value）：把引數的值壓入堆疊；原頁建議在保護模式只使用 32 位元值以維持堆疊對齊。接著呼叫程序，有傳回值時從 EAX 接收；若被呼叫者未移除引數，由呼叫者移除。", "explanation": "傳值複製的是資料本身。被呼叫者改寫參數副本，並不因此改寫呼叫者原變數；如果值本身是位址，仍可透過該位址修改被指向物。\n\n以兩個 DWORD 為例，參數共占 8 bytes。若 callee 用 RET 8 清除，caller 就不能再 ADD ESP,8；若 callee 只用 RET，caller 便須依約補回。少清或重複清都會破壞 ESP。這裡的 4-byte 建議不等於所有 ABI 的對齊規則。", "supplement": "", "printedPage": 12}, {"page": 12, "title": "傳值範例：CALL 前的 5 與 6", "translation": "資料及呼叫：\n```asm\n.data\nval1 DWORD 5\nval2 DWORD 6\n.code\npush val2\npush val1\ncall AddTwo\n```\nCALL 前的圖由高至低位址為 val2 的值 6、val1 的值 5；ESP 指向 5 所在的頂端。", "explanation": "用 S 表示壓引數前的 ESP。PUSH val2 後 ESP=S−4，[S−4]=6；PUSH val1 後 ESP=S−8，[S−8]=5。因為先壓第二個引數，再壓第一個，引數一離返回位址最近。\n\n圖上還沒有返回位址，因為它畫的是 CALL 之前。執行 CALL 才會再占 4 bytes；在 AddTwo 內建立框架後，5 對應 [EBP+8]，6 對應 [EBP+12]。", "supplement": "", "printedPage": 13}, {"page": 13, "title": "傳址呼叫的步驟", "translation": "傳址（passing by reference）：將引數的偏移位址壓入堆疊，再呼叫程序；若有傳回值則從 EAX 接收。若被呼叫者未移除引數，呼叫者須移除。", "explanation": "此處「傳址」的機制，是把位址當成引數值傳入。要交換兩個原變數，程序須先取得各位址，再讀寫該位址的內容；只交換堆疊上的指標副本不會交換原資料。\n\n例如 p 指向 val1，MOV ESI,p 取得位址，MOV EAX,[ESI] 才讀到 val1。傳值與傳址在 PUSH 時都會複製某個 32 位元值，差別在這個值被雙方約定解讀成「資料」還是「指標」。", "supplement": "", "printedPage": 14}, {"page": 14, "title": "傳址範例：Swap 的兩個位址", "translation": "原資料仍是 val1=5、val2=6，但改傳位址：\n```asm\npush OFFSET val2\npush OFFSET val1\ncall Swap\n```\nCALL 前的示意圖顯示：val2 的 offset 為 00000004，val1 的 offset 為 00000000；ESP 指向 val1 的 offset。", "explanation": "這次堆疊不是 6 和 5，而是兩個儲存位置。圖把資料起點簡化成 0，所以相鄰 DWORD 的偏移相差 4；不表示 Windows 實際把變數放在可直接使用的絕對位址 0。\n\n若 val1 在 A，val2 就在 A+4。Swap 須把 [A] 與 [A+4] 的內容互換，結果 val1=6、val2=5。這些寫入是程序實作的責任；CALL 本身不會交換資料。", "supplement": "", "printedPage": 15}, {"page": 15, "title": "CALL 之後多出的返回位址", "translation": "CALL 後的堆疊圖，由高至低位址為：val2 的值或位址、val1 的值或位址、返回位址；ESP 指向返回位址。", "explanation": "近 CALL 一方面改變 EIP，使執行轉到程序入口；另一方面先把「CALL 後下一條指令的位置」壓入堆疊，以便 RET 回來。\n\n承接前例，CALL 前 ESP=S−8，CALL 後 ESP=S−12。此時 [ESP] 是返回位址，[ESP+4] 是第一個參數，[ESP+8] 是第二個參數；這還不是 EBP 框架。再 PUSH EBP 之後，參數相對 EBP 的偏移才變成 +8、+12。", "supplement": "", "printedPage": 16}, {"page": 16, "title": "RET 與 RET n", "translation": "RET 從子程序返回：將堆疊頂端彈入指令指標 EIP 或 IP，控制流程轉到該位址。\n```asm\nret\nret n\n```\n選用的 n 表示在載入返回位址後，再把堆疊指標增加 n bytes。", "explanation": "在本章 32 位元近返回中，RET 先消耗 4-byte 返回位址。RET 8 另外略過 8 bytes 的引數；總計 ESP 比執行前增加 12。\n\n若目前 ESP 還指著區域變數或未 POP 的暫存器，RET 會把錯誤資料當成返回位址。故順序必須先恢復框架，再 RET；RET n 的 n 是 bytes 數，不是參數個數，也不是包含返回位址的總大小。", "supplement": "", "printedPage": 17}, {"page": 17, "title": "以 EBP 固定偏移存取參數", "translation": "原頁說 C／C++ 函式以相對 EBP 的常數偏移存取堆疊參數，例如 [EBP+8]。EBP 稱為基底指標或框架指標，保存堆疊框架的基底；函式執行期間不改變 EBP，返回前須恢復它原本的值。", "explanation": "固定 EBP 的好處是定位穩定：即使 ESP 因配置區域空間或 PUSH 暫存器改變，參數仍在原本的 EBP+8、EBP+12。程序用自己的 EBP 工作，結束時 POP 回呼叫者的 EBP，才能延續上一層框架。\n\n這是使用 frame pointer 的教學模型。最佳化的 C／C++ 編譯結果可以省略 EBP 框架，其他 ABI 也可能用暫存器傳參數，因此「所有 C/C++ 函式都這樣存取」會超出原例適用範圍。", "supplement": "", "printedPage": 18}, {"page": 18, "title": "AddTwo：手動基底偏移定址", "translation": "原頁 AddTwo(5,6) 的程式：\n```asm\nAddTwo PROC\n    push ebp\n    mov ebp,esp\n    mov eax,[ebp+12]\n    add eax,[ebp+8]\n    pop ebp\n    ret 8\n```\n圖中 [EBP] 是舊 EBP，[EBP+4] 是返回位址，[EBP+8]=5，[EBP+12]=6；此時 EBP 與 ESP 相同。", "explanation": "先 PUSH EBP 保存舊框架，再 MOV EBP,ESP。讀 [EBP+12] 使 EAX=6，加入 [EBP+8] 的 5，得到 11。這裡把第二參數先讀入仍正確，是因為加法交換律；下一個減法練習不能照抄相同順序。\n\n本例沒有區域變數或額外未還原的 PUSH，所以 POP EBP 前 ESP 仍等於框架基底，可直接取回舊 EBP。RET 8 接著返回並清除兩個 DWORD 引數。", "supplement": "", "printedPage": 19}, {"page": 19, "title": "8／16 位元引數的擴充", "translation": "原頁提醒：不能直接 PUSH 8 位元值；PUSH 16 位元運算元可能造成 page fault 或 ESP 對齊問題。建議先以 MOVZX 將較小引數擴充為 32 位元：\n```asm\n.data\ncharVal BYTE 'x'\n.code\nmovzx eax,charVal\npush eax\ncall Uppercase\n```", "explanation": "'x' 的字元碼為 78h。MOVZX 把來源 8 位元值放入 EAX 低位並把高位清零，得到 00000078h；PUSH EAX 按 4 bytes 傳入，維持本章參數槽配置。\n\n原頁的 fault 說法不是必然：PDF p. 45 就示範 PUSH AX 合法地讓 ESP 減 2。問題是混入 2-byte PUSH 後，ESP 不再維持原有 4-byte 邊界，與假設 4-byte 參數槽的介面可能不相容；不能說每次 PUSH AX 都會 fault。", "supplement": "MOVZX 適合無號資料／字元。若要把有號 BYTE 的 −1 保持成 32 位元 −1，應使用符號擴充 MOVSX，否則零擴充會把 FFh 解讀成 255。這是依二補數表示補充的適用條件。", "printedPage": 20}, {"page": 20, "title": "練習：Difference(30,14)", "translation": "建立 Difference 程序，計算第一引數 Val1 減第二引數 Val2：Val1−Val2。\n```asm\npush 14              ; Val2\npush 30              ; Val1\ncall Difference      ; 預期 EAX=16\n```\nCALL 前圖示 ESP 指向 30，其上一格為 14。", "explanation": "這題檢查「壓入順序」和「算術順序」是否分得清楚。右至左壓入後，建立標準框架的第一引數在 +8，第二引數在 +12。\n\n代理教學解法（手動框架版本）：\n```asm\nDifference PROC\n    push ebp\n    mov ebp,esp\n    mov eax,[ebp+8]   ; 30\n    sub eax,[ebp+12]  ; 30-14=16\n    pop ebp\n    ret 8\nDifference ENDP\n```\nEAX 先載入被減數，再減去第二參數。若反過來，結果是 −16。此片段為教學推導，未經 MASM 組譯執行。", "supplement": "", "printedPage": 21}, {"page": 21, "title": "區域變數：範圍與生命期", "translation": "原頁說明：只有子程序內的敘述能看見或修改區域變數；子程序結束時，它使用的儲存空間釋放。不同函式可有同名區域變數而不衝突。區域變數對遞迴程序及多個執行緒執行的程序十分重要。", "explanation": "同名不衝突，首先是名稱的作用域不同；每次呼叫的儲存位置也可不同。遞迴每深入一次就建立一份新框架，因此每層的 temp 不會直接覆蓋上一層 temp。\n\n「只有程序內可修改」是名稱可見性的簡化說法：如果把區域變數位址傳出去，其他程序仍能在它有效期間透過指標存取它。返回後不可繼續把該指標當成仍有效的區域儲存。區域變數也不保證整個程序就執行緒安全，仍要看共享資料。", "supplement": "", "printedPage": 23}, {"page": 22, "title": "手動配置兩個 DWORD 區域變數", "translation": "明確配置區域變數時，從 ESP 減去所需總大小。原頁配置 locA 與 locB 兩個 32 位元區域變數並初始化：\n```asm\nMySub PROC\n    push ebp\n    mov ebp,esp\n    add esp,-8\n    mov [ebp-4],123456h ; locA\n    mov [ebp-8],0       ; locB\n    ; ...\n```", "explanation": "兩個 DWORD 共需 2×4=8 bytes。ADD ESP,−8 與 SUB ESP,8 效果相同，只保留空間，還不會自動清零；後面的 MOV 才分別寫入初值。\n\nEBP−4 和 EBP−8 是各 4-byte 槽的起點。原碼沒有用具名型別或暫存器指明 MOV 的資料寬度，MASM 可能無法判定；可明確寫成 MOV DWORD PTR [EBP-4],123456h 及 MOV DWORD PTR [EBP-8],0。下一頁提供明確寬度的版本。結束時還須 MOV ESP,EBP、POP EBP 再返回。", "supplement": "", "printedPage": 24}, {"page": 23, "title": "x=10、y=20 的框架配置", "translation": "用兩個 DWORD 區域變數表示 int x=10,y=20：\n```asm\nMySub PROC\n    push ebp\n    mov ebp,esp\n    sub esp,8\n    mov DWORD PTR [ebp-4],10\n    mov DWORD PTR [ebp-8],20\n```\n圖由高至低位址：返回位址、保存的 EBP、x=10（EBP−4）、y=20（EBP−8）。", "explanation": "如果建立框架後 EBP=B，SUB ESP,8 使 ESP=B−8。x 使用 B−4 至 B−1，y 使用 B−8 至 B−5；兩塊相鄰且不重疊。\n\nDWORD PTR 是對記憶體存取寬度的指定，不是要把立即值變成指標。程式片段只展示進入與初始化，未展示退出；須先把 ESP 還原到 B，才能 POP 到保存的舊 EBP。", "supplement": "", "printedPage": 25}, {"page": 24, "title": "LEA：區域變數位址不能用 OFFSET", "translation": "LEA 取得有效位址；OFFSET 運算子只能提供組譯／連結可決定的固定偏移。要取得堆疊參數或區域變數的位址，需要 LEA。原例：\n```asm\nCopyString PROC, count:DWORD\nLOCAL temp[20]:BYTE\nmov edi,OFFSET count  ; 無效運算元\nmov esi,OFFSET temp   ; 無效運算元\n; 應該用哪條指令？\n```", "explanation": "count 與 temp 的實際位置由當次呼叫的 EBP 決定，每次呼叫可不同；OFFSET 無法把目前執行時的 EBP 算進固定常數。\n\n教學替代是 LEA EDI,count 與 LEA ESI,temp，由 MASM 將具名項目解析成框架相對定址。count 的位址與 count 的值不同：若要取數值用 MOV EDI,count；若要讓另一程序透過指標存取這個參數槽才取位址。", "supplement": "", "printedPage": 26}, {"page": 25, "title": "LEA 範例：EBP−8 的位址", "translation": "假設區域變數在 [EBP−8]，要把該變數的位址放入 ESI。不能使用：\n```asm\nmov esi,OFFSET [ebp-8] ; 錯誤\n```\n應使用：\n```asm\nlea esi,[ebp-8]\n```", "explanation": "假設 EBP=00100020h，LEA 計算 00100020h−8=00100018h，將此位址放入 ESI；它不會讀取 00100018h 裡面儲存的數值。\n\n若該位置存 20，MOV ESI,[EBP-8] 會得到 20，而 LEA ESI,[EBP-8] 得到 00100018h。這正是「值」與「位置」的差別；方括號在 LEA 中提供有效位址運算式，不表示本指令會解參考讀值。", "supplement": "", "printedPage": 27}, {"page": 26, "title": "ENTER：建立框架的指令", "translation": "ENTER 為被呼叫程序建立堆疊框架：保存 EBP、設定框架基底、保留區域變數空間。\n```asm\nMySub PROC\n    enter 8,0\n```\n在本例等價於：\n```asm\npush ebp\nmov ebp,esp\nsub esp,8\n```", "explanation": "第一個引數 8 指保留 8 bytes，第二個 0 表示此例不建立巢狀語言框架鏈。若執行前 ESP=S，保存 EBP 後為 S−4；令 EBP=S−4；再保留 8 bytes，ESP=S−12。\n\nENTER 是 CPU 指令，LOCAL／PROC 則是組譯器偽指令。這裡的等價展開只針對第二運算元為 0 的簡單情況；不要把所有 ENTER 的語意都縮成固定三行。", "supplement": "", "printedPage": 28}, {"page": 27, "title": "LEAVE：回收框架後再 RET", "translation": "LEAVE 結束程序的堆疊框架。原頁程序先 ENTER 8,0，中間執行主體，然後 LEAVE、RET。\n```asm\nenter 8,0\n; ...\nleave\nret\n```\n本例 LEAVE 的等價操作：\n```asm\nmov esp,ebp           ; 釋放區域空間\npop ebp\n```", "explanation": "MOV ESP,EBP 把堆疊頂端直接移回保存舊 EBP 的位置，所以不必逐一 POP 區域變數。POP EBP 再把上一層框架基底恢復，這時 ESP 才指向返回位址，RET 因而能正確返回。\n\n回收空間不是擦除內容；只是這段堆疊不再由本次呼叫占有。如果程序另外保存了 ESI／EBX 等必須還原的暫存器，應按它們實際存放的配置先還原；不能用 LEAVE 丟棄應恢復的值。", "supplement": "", "printedPage": 29}, {"page": 28, "title": "LOCAL：宣告有型別的區域變數", "translation": "LOCAL 宣告區域變數串列，緊接在 PROC 後方，每個變數指定型別。\n```asm\nLOCAL varlist\n\nMySub PROC\nLOCAL var1:BYTE, var2:WORD, var3:SDWORD\n```", "explanation": "LOCAL 讓組譯器替你安排堆疊位置，主體中可直接用 var1、var2、var3，不必手算所有 EBP 偏移。BYTE 是 1 byte、WORD 是 2 bytes、SDWORD 是有號 4 bytes；實際配置還可能包含對齊空間，不能只把 1+2+4 當成所有版本必然生成的框架大小。\n\n宣告只保留儲存空間，未給初值。若後續要累計 sum，必須先初始化，不能假設新區域變數從 0 開始。", "supplement": "", "printedPage": 30}, {"page": 29, "title": "LOCAL temp 的 MASM 展開", "translation": "原始宣告：\n```asm\nExample1 PROC\nLOCAL temp:DWORD\n    ; ...\n    ret\nExample1 ENDP\n```\n原頁展示 MASM 生成的形式：\n```asm\nExample1 PROC\n    push ebp\n    mov ebp,esp\n    add esp,0FFFFFFFCh ; ESP 加 -4\n    ; ...\n    mov esp,ebp\n    pop ebp\n    ret\nExample1 ENDP\n```", "explanation": "32 位元二補數中 FFFFFFFCh 代表 −4，所以 ADD ESP,FFFFFFFCh 為 temp 保留 4 bytes。temp 在本例對應 [EBP−4]，而不是全域資料區的固定位置。\n\n返回前先釋放區域空間、恢復舊 EBP，再取回返回位址。這張是「宣告與生成指令」的對照；不要把自動框架與同一份手寫框架一起重複放進同個帶參數程序，否則會多保存一次 EBP、偏移也會不同。", "supplement": "", "printedPage": 31}, {"page": 30, "title": "Example1 的框架圖", "translation": "Example1 的堆疊框架圖：返回位址位於 EBP+4；舊 EBP 位於 EBP；區域 DWORD temp 位於 EBP−4。配置完成後 ESP 指向 temp，也就是 EBP−4。", "explanation": "每格 4 bytes。EBP 保持基準不動，ESP 因 temp 的存在向下移一格；因此 EBP 和 ESP 不是永遠相同。\n\n先辨認正方向：EBP+4 往較高位址找到返回位址，EBP−4 往較低位址找到區域變數。如果此時再 PUSH EAX，ESP 會變 EBP−8，但 temp 仍在 EBP−4。這就是用 EBP 而非不斷變動的 ESP 定位區域資料的原因。", "supplement": "", "printedPage": 33}, {"page": 31, "title": "再看 INVOKE 與 32 位元限制", "translation": "本頁重述 INVOKE：32 位元模式下，可用它準備多個引數並呼叫程序。\n```asm\nINVOKE procedureName [, argumentList]\n```\n引數可為立即值／整數運算式、變數名稱、位址／ADDR 運算式或暫存器名稱；原頁再次標示不適用於 64-bit 模式。", "explanation": "現在已看過框架，可把高階寫法與堆疊連起來：INVOKE 在呼叫端安排引數，PROC 在程序端為參數命名，兩者依同一原型與呼叫慣例配合。\n\n在本章常見的右至左堆疊傳參數模型中，INVOKE AddTwo,5,6 可概念展開為 PUSH 6、PUSH 5、CALL AddTwo；其他呼叫慣例或引數型別不一定照此固定三行。Microsoft 官方 INVOKE 文件明列它是 32-bit MASM 用法。", "supplement": "", "printedPage": 34}, {"page": 32, "title": "INVOKE 的四種引數", "translation": "原頁資料與範例：\n```asm\n.data\nbyteVal BYTE 10\nwordVal WORD 1000h\n.code\nINVOKE Sub1,byteVal,wordVal ; 直接運算元\nINVOKE Sub2,ADDR byteVal   ; 變數位址\nINVOKE Sub3,eax,(10 * 20)  ; 暫存器、整數運算式\nINVOKE Sub4,[ebx]         ; 原頁稱位址運算式／間接運算元\n```", "explanation": "Sub1 收到兩個變數的值；Sub2 收到 byteVal 的位址，兩者不能混淆。Sub3 的第二個引數是組譯時可計算的 200，第一個則取呼叫當時 EAX 的內容。\n\n最後一行要釐清：普通 [EBX] 是讀 EBX 所指記憶體的內容，不等於傳 EBX 這個位址，也不等於 ADDR。只有該內容本身是一個有效指標且原型期望指標時，才構成傳入該指標；原型還須足以判定資料大小。這些範例省略各 Sub 的 PROTO，不能據此假設任意型別組合都可直接組譯。", "supplement": "", "printedPage": 35}, {"page": 33, "title": "ADDR：依記憶體模型取得指標", "translation": "ADDR 在 32 位元 INVOKE 呼叫中可用來傳遞指標引數，依程式的記憶體模型回傳 near 或 far 指標。原頁對照：Small 模型為 16-bit offset；Large 模型為 32-bit segment/offset；Flat 模型為 32-bit offset。旁註不適用於 64-bit 模式。\n```asm\n.data\nmyWord WORD ?\n.code\nINVOKE mySub,ADDR myWord\n```", "explanation": "在本章 flat 32 位元環境，ADDR myWord 提供 myWord 的 32 位元位址；myWord 自己只有 2 bytes，這不影響指標的 4-byte 大小。\n\nSmall／Large 是原頁帶入的舊式分段記憶體模型對照；Large 的「32 位元」指 segment 與 offset 的組合寬度，不能當成 flat 32-bit 線性位址的同義詞。ADDR 是 INVOKE 的組譯器運算子；不是執行時的一條 CPU ADDR 指令。", "supplement": "", "printedPage": 36}, {"page": 34, "title": "INVOKE Swap：先自行展開", "translation": "原頁宣告 20 個未初始化 DWORD，並要求對照 INVOKE 與相對應程式碼：\n```asm\n.data\nArray DWORD 20 DUP(?)\n.code\n; ...\nINVOKE Swap, ADDR Arrary, ADDR [Array+4]\n```\n原頁「Corresponding Code」下方以青色方塊遮住答案；下一頁揭露。", "explanation": "先判斷要交換哪兩個物件：第一個是 Array[0]，第二個是 Array[1]。DWORD 每格 4 bytes，因此第二元素的位址是 Array+4，不是 Array+1。\n\n教學推導：若第一參數為第一元素位址、第二參數為第二元素位址，採右至左傳入時要先壓 Array+4，再壓 Array。原頁 Arrary 是拼字錯誤，應為已宣告的 Array；保留原文並在下一頁給出修正形式。20 DUP(?) 只配置空間，未給可交換的確定初值。", "supplement": "", "printedPage": 37}, {"page": 35, "title": "INVOKE Swap：展開答案與拼字勘誤", "translation": "本頁與前頁同題，原呼叫仍寫成：\n```asm\nINVOKE Swap, ADDR Arrary, ADDR [Array+4]\n```\n這次揭露對應程式碼：\n```asm\npush OFFSET Array+4\npush OFFSET Array\ncall Swap\n```\n資料宣告仍為 Array DWORD 20 DUP(?)。", "explanation": "勘誤：宣告的是 Array，呼叫中的 Arrary 應改為 Array。修正後概念寫法為 INVOKE Swap,ADDR Array,ADDR [Array+4]。\n\n兩次 PUSH 都傳位址，不讀取陣列元素；原型可寫 Swap PROTO,pValX:PTR DWORD,pValY:PTR DWORD。交換過程才經由這兩個指標讀寫元素。如果陣列未先初始化，雖可談位址配置，卻不能宣稱交換後有哪兩個固定數值。", "supplement": "", "printedPage": 38}, {"page": 36, "title": "再看 PROC 參數宣告", "translation": "本頁重述 PROC：宣告程序並可附具名參數串列；各參數以逗號分隔，形式為 paramName:type。型別可為 BYTE、SBYTE、WORD 等標準型別，或指向這些型別的指標。原頁列 label PROC paramList，並附 64-bit 不適用警語。", "explanation": "前面已把參數看成框架中的位置，這裡可重新理解型別：名稱供人閱讀，型別讓 MASM 知道讀取幾 bytes，以及 INVOKE 應如何檢查引數。\n\n例如 pValX:PTR DWORD 的參數槽保存位址；若寫 MOV EAX,pValX，是載入指標，不是直接讀取它指向的 DWORD。仍須再以 [EAX] 等間接定址解參考。PROC 這個指令本身也有 x64 形式，限制應讀成本章參數配置的限制。", "supplement": "", "printedPage": 39}, {"page": 37, "title": "再看參數串列與逗號", "translation": "參數串列可放一行或多行；另起行時格式為：\n```asm\nlabel PROC,\n    param1:type1,\n    param2:type2,\n    ; ...\n    paramN:typeN\n```\n原頁另列同一行以逗號分隔的方式，並以箭頭指出 PROC 後的逗號不可省略。", "explanation": "這是 PDF p. 3 的重複內容，仍保留實體頁碼。現在可以用它檢查後面 FillArray：fillVal:BYTE 後還有 arraySize:DWORD，所以兩者之間需要逗號。\n\n程序宣告最後一個參數後不必為了換行再加逗號。不要把逗號放入名稱或型別，因為它是參數間的分隔符，而不是型別的一部分。", "supplement": "", "printedPage": 40}, {"page": 38, "title": "再看具名 AddTwo", "translation": "AddTwo 接收兩整數，以 EAX 回傳和。本頁重列：\n```asm\nAddTwo PROC,\n    val1:DWORD, val2:DWORD\n    mov eax,val1\n    add eax,val2\n    ret\nAddTwo ENDP\n```", "explanation": "把本頁與下一頁成對讀：這裡用 val1／val2，下一頁會改寫成 [EBP+8]／[EBP+0Ch]。因此具名參數讓原始碼更易讀，底層仍是框架相對存取。\n\n程序承諾 EAX 帶回結果；輸入 5、6 時，MOV 取 5，ADD 得 11，退出框架不應把 EAX 用 POPAD 或其他還原操作覆蓋回舊值。", "supplement": "", "printedPage": 41}, {"page": 39, "title": "具名參數如何變成 EBP 偏移", "translation": "MASM 將 AddTwo 的參數名稱轉成相對 EBP 的偏移；原頁展開：\n```asm\nAddTwo PROC\n    push ebp\n    mov ebp,esp\n    mov eax,DWORD PTR [ebp+8]\n    add eax,DWORD PTR [ebp+0Ch]\n    leave\n    ret 8\nAddTwo ENDP\n```", "explanation": "0Ch 就是十進位 12。第一個參數的位移 +8，來自舊 EBP 的 4 bytes 與返回位址的 4 bytes；第二個再往上 4 bytes，所以是 +12。\n\nLEAVE 恢復舊框架，RET 8 返回並清除兩個 DWORD 引數。這是講義在其 MASM 設定下展示的展開結果，不表示不同語言慣例、prologue 選項或版本必定逐字生成同樣指令。", "supplement": "", "printedPage": 42}, {"page": 40, "title": "Swap 與 ReadFile 的介面", "translation": "原頁提供兩個程序範本：\n```asm\nSwap PROC,\n    pValX:PTR DWORD,\n    pValY:PTR DWORD\n    ; ...\nSwap ENDP\n\nReadFile PROC,\n    pBuffer:PTR BYTE\nLOCAL fileHandle:DWORD\n    ; ...\nReadFile ENDP\n```", "explanation": "Swap 的兩個指標讓程序能改寫兩個 DWORD；ReadFile 的 pBuffer 是外部傳入的位址，而 fileHandle 是這次呼叫自己使用的區域 DWORD。\n\n兩者在框架的位置性質不同：參數位於正偏移，區域變數通常在負偏移。PTR BYTE 表示緩衝區元素按 byte 解讀，不提供緩衝區長度或讀入上限。原頁只展示介面，省略實作及退出流程；此 ReadFile 名稱也不能據此認定為完整 Windows API 宣告。", "supplement": "", "printedPage": 43}, {"page": 41, "title": "FillArray：補上寫入與位址遞增", "translation": "FillArray 接收 byte 陣列指標、要複製到每個元素的單一 byte 值，以及陣列大小。原頁程式骨架：\n```asm\nFillArray PROC,\n    pArray:PTR BYTE, fillVal:BYTE\n    arraySize:DWORD\n    mov ecx,arraySize\n    mov esi,pArray\n    mov al,fillVal\nL1: mov ; 運算元以青色遮住\n    inc ; 運算元以青色遮住\n    loop L1\n    ret\nFillArray ENDP\n```\n完整揭露在下一頁；原頁 fillVal:BYTE 後漏逗號。", "explanation": "先依三個準備步驟推理：ECX 是剩餘次數，ESI 是目前元素位址，AL 是填入值。迴圈每次應把 AL 寫到 [ESI]，再將 ESI 加 1，才能移到下一個 BYTE。\n\n教學填空為 MOV [ESI],AL 與 INC ESI。LOOP 會先讓 ECX 減 1，再於非零時跳回；因此本骨架需要 arraySize>0。若長度為 0，卻先進入主體，就會寫入不應寫的元素，之後還可能發生極長迴圈。", "supplement": "", "printedPage": 44}, {"page": 42, "title": "FillArray：完整流程與邊界修正", "translation": "本頁揭露 FillArray 的迴圈：\n```asm\nFillArray PROC,\n    pArray:PTR BYTE, fillVal:BYTE\n    arraySize:DWORD\n    mov ecx,arraySize\n    mov esi,pArray\n    mov al,fillVal\nL1: mov [esi],al\n    inc esi\n    loop L1\n    ret\nFillArray ENDP\n```\n輸入及用途與前頁相同：將指定 byte 填入整個 byte 陣列。原碼仍漏了 fillVal 後的逗號。", "explanation": "以 pArray=A、fillVal=7、arraySize=3 為例：初始 ECX=3、ESI=A、AL=7；三輪分別寫 [A]、[A+1]、[A+2]，每輪 ESI 加 1，ECX 依序變 2、1、0，最後不跳回。\n\n教學修正分三件事：①在 fillVal:BYTE 後補逗號；②在第一次寫入前加 JECXZ Done，讓 0 長度直接退出；③若介面要求保存 ESI，使用 USES ESI 或正確的保存／還原。Done 應放在 RET 前。傳入非零長度時，也須確保緩衝區有至少該長度可寫；原例未做界限檢查。", "supplement": "", "printedPage": 45}, {"page": 43, "title": "讀值還是取位址：先預測結果", "translation": "原頁陣列與指令：\n```asm\n.data\nEx1Array SDWORD 10,-20,30,50,40,-2\n.code\nmain PROC\n    mov eax,Ex1Array+12\n    mov ebx,[Ex1Array+12]\n    mov ecx,OFFSET Ex1Array+12\n    lea edx,Ex1Array+12\n    call DumpRegs\n    ; ...\n```\n下方輸出在本頁以青色方塊遮住；下一頁揭露結果。", "explanation": "每個 SDWORD 占 4 bytes，所以 +12 位移到索引 3 的第四元素 50。MASM 的具型別資料標號可直接表示記憶體運算元，因此前兩條 MOV 都讀取該元素的值；是否有方括號不是唯一判斷依據。\n\nOFFSET 與 LEA 則都在此例取得第四元素的位址。先預測 EAX=EBX=50、ECX=EDX=該位址，再看下一頁。這個 MASM 語法不能直接類比其他組譯器的所有同形寫法。", "supplement": "", "printedPage": 46}, {"page": 44, "title": "讀值與取位址：暫存器結果", "translation": "原碼與前頁相同。註解換算 50=16×3+2=00000032h。DumpRegs 圖顯示：\n```text\nEAX=00000032  EBX=00000032\nECX=00404010  EDX=00404010\nESI=00000000  EDI=00000000\nEBP=0018FF90  ESP=0018FF88\nEIP=0040101B  EFL=00000246\nCF=0 SF=0 ZF=1 OF=0 AF=0 PF=1\n```\n前兩個是第四元素的值，後兩個是該次範例執行的位址。", "explanation": "50 除 16 得商 3、餘 2，故十六進位為 32h。EAX／EBX 都是 00000032h；ECX／EDX 的 00404010h 則指向該資料。反推本次陣列起點為 00404010h−0Ch=00404004h。\n\n位址只是這張圖的執行結果，重新連結或載入後可能不同。這段 MOV 與 LEA 不負責計算 50−某值，故不可把畫面上的 ZF=1 等旗標硬解成「剛做了比較」；旗標可能來自先前狀態。", "supplement": "", "printedPage": 47}, {"page": 45, "title": "TestStack：追蹤不同寬度的 PUSH", "translation": "原頁程序及觀察值（十六進位）：\n```asm\nTestStack PROC,\n    arg1:WORD,\n    arg2:BYTE\nLOCAL temp[10]:BYTE\n    call DumpRegs         ; ESP=0019FF58, EBP=0019FF64\n    mov ax,arg1\n    push eax\n    call DumpRegs         ; ESP=0019FF54\n    push ax\n    call DumpRegs         ; ESP=0019FF52\n    push WORD PTR 10\n    call DumpRegs         ; ESP=0019FF50\n    push 10\n    call DumpRegs         ; ESP=0019FF4C\n    ret 8\nTestStack ENDP\n```\n圖另記「呼叫 TestStack 前 ESP=0019FF74」。", "explanation": "由 FF74 到框架 EBP=FF64 共減 10h=16 bytes，可與兩個各占 4 bytes 的引數槽、返回位址、舊 EBP 對應。LOCAL temp[10]:BYTE 後 ESP=FF58，比 EBP 再低 0Ch=12 bytes：圖展示了局部配置含對齊的情況，不只配置 10 bytes。\n\n接著從 FF58 起，PUSH EAX 減 4，PUSH AX 減 2，PUSH WORD PTR 10 減 2，PUSH 10 在本模式減 4，得到 FF54、FF52、FF50、FF4C。MOV AX,arg1 只更新 EAX 的低 16 位，所以隨後 PUSH EAX 的高 16 位不可假定為零。\n\nRET 8 清的是兩個引數槽，不是前面測試 PUSH 的 12 bytes。原頁依賴 MASM 自動 epilogue 恢復 ESP／EBP；如果改成完全手寫框架而直接 RET 8，會從錯誤位置取返回位址。圖中的 DumpRegs 數值視為觀察呼叫者狀態，並非要額外永久累計每個 CALL 的返回位址。", "supplement": "", "printedPage": 48}, {"page": 46, "title": "多模組程式的建置流程", "translation": "多模組程式將原始程式分成不同 ASM 檔案。每個 ASM 檔案（模組）各自組譯為 OBJ；同一程式的全部 OBJ 再由 link 工具連結為單一 EXE。", "explanation": "分清兩個階段：組譯器處理單個模組內的指令與符號，產生機器碼及待解析的外部符號；連結器把各模組放在一起，解析跨模組的名稱與位址。\n\n所以 PROTO 能讓呼叫端知道介面，卻不能憑空補出程序的機器碼。若組譯成功但找不到外部函式實作，仍會在連結階段失敗。流程圖為「main.asm→main.obj」及「helper.asm→helper.obj」，兩者再一起連到程式 EXE。", "supplement": "", "printedPage": 49}, {"page": 47, "title": "多模組的優點與封裝條件", "translation": "大型程式分成來源模組後較容易撰寫、維護、除錯。修改一行程式時，通常只需重新組譯它所屬的模組；已組譯模組的連結所需時間較少。模組可集中邏輯相關的程式與資料。\n\n原頁把封裝說明為：程序與變數在模組內自動隱藏，除非將它們宣告為 public。", "explanation": "拆分讓每個模組有可理解的責任，例如一個處理輸入、一個加總、一個顯示。修改加總實作時，若介面不變，其餘模組的原始碼可能不必重組。\n\n但原頁的 public 說法需要條件：MASM 的程序可見性也受預設與選項影響，不能保證每個 PROC 自動 private。應檢查實際 PUBLIC／PRIVATE 及匯出符號設定。若共同 include 的介面變更，所有依賴它的模組也可能都要重組；「只重組一個」不是所有變更都成立。", "supplement": "", "printedPage": 50}, {"page": 48, "title": "建立多模組程式的步驟", "translation": "基本步驟：建立主模組；為每個程序或一組相關程序建立獨立來源模組；建立 include 檔，放入外部程序（跨模組呼叫者）的原型；使用 INCLUDE 讓各模組都取得這些原型。", "explanation": "先定介面，再分工實作。例如 main 呼叫 ArraySum，把 ArraySum 的 PROTO 放進共同 sum.inc；main.asm 與實作模組都 INCLUDE 它，讓型別與順序有共同依據。\n\nINCLUDE 是組譯前／組譯時引入宣告內容，不會把另一個 OBJ 自動連入 EXE。仍要組譯實作模組並在連結時提供它；宣告、實作、可見性與連結輸入四件事都要配合。", "supplement": "", "printedPage": 51}, {"page": 49, "title": "sum.inc：三個外部程序的原型", "translation": "sum.inc 包含不在 Irvine32 函式庫內的外部函式原型：\n```asm\nINCLUDE Irvine32.inc\nPromptForIntegers PROTO,\n    ptrPrompt:PTR BYTE,  ; 提示字串\n    ptrArray:PTR DWORD,  ; 陣列\n    arraySize:DWORD     ; 陣列大小\nArraySum PROTO,\n    ptrArray:PTR DWORD,  ; 陣列\n    count:DWORD         ; 元素數\nDisplaySum PROTO,\n    ptrPrompt:PTR BYTE,  ; 提示字串\n    theSum:DWORD        ; 陣列總和\n```", "explanation": "三個介面串成資料流：PromptForIntegers 用提示字串引導輸入，把數值寫入陣列；ArraySum 根據陣列位址和長度求和；DisplaySum 接收提示及已算出的和。\n\n前兩者都需要指標加長度，第三者接收的是總和值，不是指向總和的指標。此頁只有原型，未展示完整實作或所有回傳約定；不可僅憑原型就說已執行並得到結果。也不要以為 INCLUDE Irvine32.inc 已包含這三個自訂程序。", "supplement": "", "printedPage": 52}, {"page": 50, "title": "作業三：CountMatches 規格", "translation": "撰寫 CountMatches：接收兩個有號雙字陣列的指標，以及第三個參數表示兩陣列共同長度。對每個第一陣列的元素 xᵢ，若同位置 yᵢ 相等，計數加一，最後用 EAX 回傳相等元素的數量。\n\n另寫測試程式，呼叫 CountMatches 並傳入兩組不同的陣列配對。用 INVOKE 傳遞堆疊參數，為 CountMatches 建立 PROTO；程序改動的暫存器，除了 EAX 之外都須保存並還原。\n\n加分題（額外 2 分）：計算所有相符元素，不限相同位置。", "explanation": "基本題是逐位置比較，不是搜尋另一陣列任意位置。教學介面可寫 CountMatches PROTO,pX:PTR SDWORD,pY:PTR SDWORD,count:DWORD。\n\n流程：EAX=0；若 count=0 直接返回；用兩個指標各讀一個 DWORD，以 CMP 判斷相等，相等才增加 EAX；兩指標各加 4，重複 count 次。CMP 不能直接同時使用兩個一般記憶體運算元，因此先把其中一個元素載入暫存器。\n\n保存 ESI／EDI／ECX／EDX 等實際改動的暫存器；不要把 EAX 的結果還原掉。加分題可用外層取 xᵢ、內層搜尋 yⱼ；下一頁的「無重複元素」假設讓匹配數有明確集合交集解讀。", "supplement": "", "printedPage": 53}, {"page": 51, "title": "作業三：基本 2 筆、加分 5 筆", "translation": "基本題對下列陣列回報 2 筆匹配：\n```asm\narray1 SDWORD 10,5,4,-6,2,11,12\narray2 SDWORD 10,5,3,1,4,2,-6\n```\n加分題對相同兩陣列回報 5 筆匹配。原頁特別假設陣列中沒有重複元素。", "explanation": "基本題依序比較：(10,10) 相等、(5,5) 相等，接著 (4,3)、(−6,1)、(2,4)、(11,2)、(12,−6) 都不相等，所以 EAX=2。\n\n加分題允許跨位置，兩陣列共同元素為 10、5、4、−6、2，共 5 個。11 與 12 不在第二陣列，因此不計。若不允許位置不同的匹配，就不能把結果算成 5。\n\n代理測試設計另包含空陣列、全相等、完全不相等與負數；演算法模型測試及 MASM 原生執行的狀態分別記錄在交付報告。若允許重複，須先決定是交集不同值數、成功找到的元素數，還是所有相等配對數，原題沒有替重複情況下定義。", "supplement": "", "printedPage": 54}], "slides": [{"number": 1, "title": "從 CALL／RET 到完整程序介面", "bullets": ["主線：介面 → 引數 → 框架 → 區域資料 → 跨模組", "32 位元 MASM；本章堆疊模型不直接套到 x64", "保留 51 個 PDF 頁碼，重複頁與練習頁不略過"], "speaker": "教學目的：建立本章地圖。先詢問 CALL 如何知道回哪裡，再追問兩個數如何交給程序。說明介面、實作與呼叫慣例各負責一部分；先理解手動堆疊，再讀 MASM 的便利寫法。易錯處：把所有 PROC 都誤認為 64 位元不支援。", "refs": "1–9"}, {"number": 2, "title": "PROTO、PROC、INVOKE 各做什麼", "bullets": ["PROTO：先提供參數介面", "PROC...ENDP：定義程序主體", "INVOKE：依原型及呼叫慣例準備引數並呼叫"], "speaker": "教學目的：分清組譯期與執行期。以 MySub 為例，先寫 PROTO，再寫呼叫，最後寫主體；原型沒有可執行實作。將 ArraySum 的指標及長度拆開讀。易錯處：漏掉 PROC 後或換行參數間的逗號。", "refs": "2–8"}, {"number": 3, "title": "傳值與傳址：堆疊裡放了什麼", "bullets": ["傳值：複製 5、6；改副本不直接改原變數", "傳址：複製 A、A+4；解參考才能改原資料", "參數槽大小與被指向資料大小是兩回事"], "speaker": "教學目的：以 AddTwo 與 Swap 比較。畫出變數與參數槽兩層：第一層是呼叫端資料，第二層是堆疊複本；用箭頭表示傳址。指出圖中 0 與 4 是簡化 offset，不能直接當作實際可用的絕對位址。", "refs": "10–15"}, {"number": 4, "title": "5、6 如何走進 AddTwo", "bullets": ["PUSH 6 → PUSH 5 → CALL AddTwo", "CALL 再壓入返回位址", "PUSH EBP；MOV EBP,ESP 後：+8 是 5，+12 是 6"], "speaker": "教學目的：自己推得偏移，不死背。令原 ESP=S，逐步寫出 S−4、S−8、S−12、S−16；最後 EBP=S−16，第一參數相差 8 bytes。用互動框架追蹤確認各個階段。", "refs": "9、12、15、18"}, {"number": 5, "title": "RET 8 的 8 是 bytes", "bullets": ["先取回 4-byte 返回位址，再略過 8-byte 引數", "框架與保存暫存器須先恢復", "清理由誰做取決於慣例；不能重複清除"], "speaker": "教學目的：區分返回位址和引數回收。帶學生從 POP EBP 後的 ESP 位置算起，RET 8 總共讓 ESP 增加 12。再比較只用 RET 並由 caller ADD ESP,8 的情況。易錯處：把 8 當成參數數量或含返回位址的大小。", "refs": "11、16–18、39"}, {"number": 6, "title": "減法測出參數順序", "bullets": ["Difference(30,14) 應得到 16", "MOV EAX,[EBP+8]；SUB EAX,[EBP+12]", "右至左壓入不代表算式也反過來"], "speaker": "教學目的：讓加法掩蓋不了順序錯誤。先讓讀者預測照抄上一張先取 +12 會怎樣，再求正確 30−14。說明手動框架版本與具名 PROC 版本二選一，避免重複 prologue。", "refs": "18–20"}, {"number": 7, "title": "小型別與 PUSH 寬度", "bullets": ["BYTE 不可直接用 PUSH r/m8", "無號小值用 MOVZX；有號值須留意 MOVSX", "PUSH AX 減 2，PUSH EAX 減 4；與介面配置須一致"], "speaker": "教學目的：拆開資料型別、參數槽與指令運算元寬度。先計算 x 的 78h 零擴充；再用 TestStack 的 FF58→FF54→FF52 追蹤。易錯處：宣稱 16-bit PUSH 每次都會 fault，或以為 MOV AX 會清掉 EAX 高半部。", "refs": "19、45"}, {"number": 8, "title": "區域變數放在 EBP 的另一側", "bullets": ["參數常在正偏移；區域資料常在負偏移", "兩個 DWORD 共保留 8 bytes", "每次呼叫各有框架；LOCAL 不會自動初始化"], "speaker": "教學目的：畫 x 在 −4、y 在 −8，和參數 +8 比較。區分名稱作用域與儲存生命期，再說遞迴各層有各自 temp。易錯處：把局部變數當作其他程序絕對無法透過指標存取的資料。", "refs": "21–23、28–30"}, {"number": 9, "title": "MOV、OFFSET、LEA、ADDR", "bullets": ["MOV：依運算元讀值", "OFFSET：靜態可決定的偏移；LEA：執行時計算有效位址", "ADDR：INVOKE 的取位址語法；指標不等於內容"], "speaker": "教學目的：先用 EBP=00100020h 算 LEA [EBP−8] 得 00100018h，再假設該處存 20 比較 MOV 的結果。回到 Ex1Array+12，說明 MASM 具型別標號直接也是記憶體運算元。", "refs": "24–25、32–35、43–44"}, {"number": 10, "title": "ENTER／LEAVE 與自動框架", "bullets": ["ENTER 8,0：保存 EBP、建立基準、保留 8 bytes", "LEAVE：MOV ESP,EBP；POP EBP", "PROC／LOCAL 是組譯器語法；ENTER／LEAVE 是指令"], "speaker": "教學目的：手動三行對照 ENTER，再把退出反向追蹤。區分釋放與清零。易錯處：丟棄應還原的保存暫存器，或同時保留 MASM 自動框架與重複手寫 prologue。", "refs": "26–30、39"}, {"number": 11, "title": "從具名參數到實際偏移", "bullets": ["val1 → DWORD PTR [EBP+8]", "val2 → DWORD PTR [EBP+0Ch]", "指標參數先取位址，再用間接定址讀寫"], "speaker": "教學目的：將 AddTwo 的兩個版本上下對照；0Ch=12 先換算，再從兩個 4-byte 框架項目推偏移。以 Swap 的 PTR DWORD 和 ReadFile 的 PTR BYTE 區分指向型別與指標寬度。", "refs": "36–40"}, {"number": 12, "title": "FillArray：可追蹤的迴圈", "bullets": ["ECX=長度；ESI=目前位址；AL=填入值", "MOV [ESI],AL → INC ESI → LOOP", "修正逗號、0 長度入口及 ESI 保存條件"], "speaker": "教學目的：用三個 byte 都填 7 的例子追蹤三輪。先在遮答案頁推理缺少運算元，再看揭露頁。易錯處：arraySize=0 仍先寫一個 byte，LOOP 再下溢；指標非空也不等於有足夠可寫空間。", "refs": "41–42"}, {"number": 13, "title": "暫存器實驗：值與位址分家", "bullets": ["Ex1Array+12 對應第四個 SDWORD：50=32h", "EAX=EBX=00000032h", "ECX=EDX=00404010h 是原圖該次執行的位址"], "speaker": "教學目的：把 12 bytes 除 4 得索引 3，讀出 50，再換十六進位。追問若陣列重新載入，哪一組通常不變？數值不因載入位址改變，但取址結果可能改變。不要把 DumpRegs 的旗標當成這幾條 MOV 做出的比較。", "refs": "43–45"}, {"number": 14, "title": "多模組：宣告、組譯、連結", "bullets": ["各 ASM → 各 OBJ → link → 單一 EXE", "共同 .inc 放跨模組原型，INCLUDE 分享宣告", "可見性與連結輸入須配合；原型不等於實作"], "speaker": "教學目的：以 main、輸入、加總、顯示模組畫資料流。修改介面時可能需重組所有依賴模組。易錯處：以為 INCLUDE 會自動連入函式實作，或把所有 PROC 都當作預設 private。", "refs": "46–49"}, {"number": 15, "title": "CountMatches：先把基本規格寫清楚", "bullets": ["輸入：兩個 PTR SDWORD 與共同長度", "逐位置相等才累計；EAX 傳回", "改動的其他暫存器須恢復；空陣列先返回"], "speaker": "教學目的：把規格變成迴圈不變量：已比較前 i 個位置，EAX 等於其中相等數。CMP 前將一側載入暫存器，兩個指標每輪加 4。原題另要求兩組陣列測試、PROTO 與 INVOKE，不能只交函式。", "refs": "50–51"}, {"number": 16, "title": "基本 2、加分 5：同一資料不同問題", "bullets": ["逐位置：只有 10 與 5 在同位置相等 → 2", "跨位置：共同元素 10、5、4、−6、2 → 5", "原題假設無重複；有重複時須重訂計數語意"], "speaker": "教學目的：逐對讀七個位置，再在第二陣列搜尋第一陣列各值，讓兩種算法差異可見。用互動比對改成無匹配或全匹配的資料。模型測試可驗證預期值，但不等於 MASM 原生機器碼已執行。", "refs": "50–51"}], "notes": "---\ntitle: \"組合語言 第八章：進階程序與堆疊框架\"\ncourse: assembly-language\nunit: chapter-8\ncreated: 2026-11-05\nupdated: 2026-11-05\nstatus: reviewed\nstandard_version: \"1.1\"\nsource_ids: [src-20261105-assembly-ch8, web-20261105-microsoft-masm-procedures]\ncoverage: \"PDF pp. 1–51；完整逐頁翻譯與講解；無未完成頁段\"\n---\n\n# 組合語言 第八章：進階程序與堆疊框架\n\n[Wiki](../../wiki/index.md) · [原始 PDF](../../raw/pdfs/1151%20ch8.pdf) · [來源與勘誤](../../wiki/sources/src-20261105-assembly-ch8.md) · [網站](../../index.html#/assembly-language/chapter-8/pages/1)\n\n## 來源與閱讀說明\n\n按 PDF 實體頁序一頁一節。原頁尾編號因混編而不連續，逐頁另列；引用一律使用 PDF 頁序。\n以繁體中文完整意譯，保留程式關鍵語法；重複頁尾不逐次抄寫。原文、觀念講解與選用補充分開；教學修正明示，不改原 PDF。遮住答案的頁面依可見內容呈現，下一頁揭露答案。\n主要適用 32 位元 MASM／Irvine 教學模型。程式未經 MASM／Irvine32 原生組譯執行，Python 模型測試只核對演算法與位移。原作者 Kip R. Irvine，封面為 2015 第七版，含 2007 版與課堂增補；講義發布日期未知。\n\n## 逐頁目錄\n\n- [PDF p. 1：第八章：進階程序](#pdf-p-1)\n- [PDF p. 2：PROC：具名參數與型別](#pdf-p-2)\n- [PDF p. 3：PROC：參數換行格式](#pdf-p-3)\n- [PDF p. 4：AddTwo：兩整數相加](#pdf-p-4)\n- [PDF p. 5：INVOKE：帶引數呼叫](#pdf-p-5)\n- [PDF p. 6：PROTO：先宣告介面](#pdf-p-6)\n- [PDF p. 7：PROTO、INVOKE 與實作的位置](#pdf-p-7)\n- [PDF p. 8：ArraySum 的指標與長度原型](#pdf-p-8)\n- [PDF p. 9：堆疊框架的建立](#pdf-p-9)\n- [PDF p. 10：堆疊參數與暫存器參數](#pdf-p-10)\n- [PDF p. 11：傳值呼叫的步驟](#pdf-p-11)\n- [PDF p. 12：傳值範例：CALL 前的 5 與 6](#pdf-p-12)\n- [PDF p. 13：傳址呼叫的步驟](#pdf-p-13)\n- [PDF p. 14：傳址範例：Swap 的兩個位址](#pdf-p-14)\n- [PDF p. 15：CALL 之後多出的返回位址](#pdf-p-15)\n- [PDF p. 16：RET 與 RET n](#pdf-p-16)\n- [PDF p. 17：以 EBP 固定偏移存取參數](#pdf-p-17)\n- [PDF p. 18：AddTwo：手動基底偏移定址](#pdf-p-18)\n- [PDF p. 19：8／16 位元引數的擴充](#pdf-p-19)\n- [PDF p. 20：練習：Difference(30,14)](#pdf-p-20)\n- [PDF p. 21：區域變數：範圍與生命期](#pdf-p-21)\n- [PDF p. 22：手動配置兩個 DWORD 區域變數](#pdf-p-22)\n- [PDF p. 23：x=10、y=20 的框架配置](#pdf-p-23)\n- [PDF p. 24：LEA：區域變數位址不能用 OFFSET](#pdf-p-24)\n- [PDF p. 25：LEA 範例：EBP−8 的位址](#pdf-p-25)\n- [PDF p. 26：ENTER：建立框架的指令](#pdf-p-26)\n- [PDF p. 27：LEAVE：回收框架後再 RET](#pdf-p-27)\n- [PDF p. 28：LOCAL：宣告有型別的區域變數](#pdf-p-28)\n- [PDF p. 29：LOCAL temp 的 MASM 展開](#pdf-p-29)\n- [PDF p. 30：Example1 的框架圖](#pdf-p-30)\n- [PDF p. 31：再看 INVOKE 與 32 位元限制](#pdf-p-31)\n- [PDF p. 32：INVOKE 的四種引數](#pdf-p-32)\n- [PDF p. 33：ADDR：依記憶體模型取得指標](#pdf-p-33)\n- [PDF p. 34：INVOKE Swap：先自行展開](#pdf-p-34)\n- [PDF p. 35：INVOKE Swap：展開答案與拼字勘誤](#pdf-p-35)\n- [PDF p. 36：再看 PROC 參數宣告](#pdf-p-36)\n- [PDF p. 37：再看參數串列與逗號](#pdf-p-37)\n- [PDF p. 38：再看具名 AddTwo](#pdf-p-38)\n- [PDF p. 39：具名參數如何變成 EBP 偏移](#pdf-p-39)\n- [PDF p. 40：Swap 與 ReadFile 的介面](#pdf-p-40)\n- [PDF p. 41：FillArray：補上寫入與位址遞增](#pdf-p-41)\n- [PDF p. 42：FillArray：完整流程與邊界修正](#pdf-p-42)\n- [PDF p. 43：讀值還是取位址：先預測結果](#pdf-p-43)\n- [PDF p. 44：讀值與取位址：暫存器結果](#pdf-p-44)\n- [PDF p. 45：TestStack：追蹤不同寬度的 PUSH](#pdf-p-45)\n- [PDF p. 46：多模組程式的建置流程](#pdf-p-46)\n- [PDF p. 47：多模組的優點與封裝條件](#pdf-p-47)\n- [PDF p. 48：建立多模組程式的步驟](#pdf-p-48)\n- [PDF p. 49：sum.inc：三個外部程序的原型](#pdf-p-49)\n- [PDF p. 50：作業三：CountMatches 規格](#pdf-p-50)\n- [PDF p. 51：作業三：基本 2 筆、加分 5 筆](#pdf-p-51)\n\n<a id=\"pdf-p-1\"></a>\n## PDF p. 1｜第八章：進階程序\n\n來源：[原 PDF 第 1 頁](../../raw/pdfs/1151%20ch8.pdf#page=1)（封面無印刷頁碼） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n《x86 處理器組合語言》第七版、全球版。作者 Kip R. Irvine；第八章：進階程序（Advanced Procedures）。投影片由作者製作，Pearson Education © 2015。\n\n原頁授權聲明：可為個人或課堂用途修改、複製本投影片，但須保留版權聲明、作者姓名與標題。原檔完整保留此聲明；網站另用自製學習封面。\n\n### 觀念講解\n\n本章要把「CALL 到某處，RET 回來」擴充成可重用的程序介面：呼叫者如何交付資料、被呼叫者如何找參數及區域變數、最後如何恢復堆疊。\n\n閱讀先備是暫存器、MOV、PUSH／POP、CALL／RET 與基本定址。本教材主要採 32 位元 MASM、EBP 堆疊框架與類 stdcall 的例子；它不是所有 x86／C++／x64 程式的通用配置。\n\n<a id=\"pdf-p-2\"></a>\n## PDF p. 2｜PROC：具名參數與型別\n\n來源：[原 PDF 第 2 頁](../../raw/pdfs/1151%20ch8.pdf#page=2)（內文 p. 2） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nPROC 偽指令宣告程序，並可附上具名參數串列。基本表示為：\n```asm\nlabel PROC paramList\n; 每個參數：paramName:type\n```\nparamList 內參數以逗號分隔。type 可為 BYTE、SBYTE、WORD 等標準組合語言型別，也可為指向這些型別的指標。原頁旁註「不適用於 64-bit 模式」。\n\n### 觀念講解\n\n參數名稱是組譯器提供的符號，不是新增 CPU 暫存器。例如 val1:DWORD 告訴 MASM 此參數按 32 位元資料使用；p:PTR DWORD 表示傳入指標，指向 DWORD 資料，而不是直接傳入那個 DWORD。\n\n帶參數的實際常用寫法是下一頁的「程序名 PROC, 參數串列」；本頁是概略語法。PROC 在組譯時建立程序結構及符號，CPU 執行的是它生成的指令。\n\n### 教學補充／提醒\n\n範圍釐清：本頁的 64-bit 警語應限於這套 32 位元具名堆疊參數用法，不能推成「ml64 完全沒有 PROC」。官方 PROC 文件另有 x64 的 FRAME 語法；見本單元 Microsoft 查證來源。\n\n<a id=\"pdf-p-3\"></a>\n## PDF p. 3｜PROC：參數換行格式\n\n來源：[原 PDF 第 3 頁](../../raw/pdfs/1151%20ch8.pdf#page=3)（內文 p. 3） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n參數串列可另起一行或多行，PROC 後須有逗號：\n```asm\nlabel PROC,\n    paramList\n```\n可在同一行寫多個參數：\n```asm\nparam1:type1, param2:type2, ..., paramN:typeN\n```\n也可每行一個；除最後一個參數外，各項之間仍須有逗號。原圖箭頭特別指出 PROC 後的逗號。\n\n### 觀念講解\n\n換行只是排版，逗號才負責分隔。先看程序名稱，再列「名稱:型別」；如果第二行仍有下一個參數，上一行末尾要保留逗號。\n\n這個規則在 PDF pp. 41–42 的 FillArray 將再次用到：原碼少一個分隔逗號，不應因換行而以為可以省略。\n\n<a id=\"pdf-p-4\"></a>\n## PDF p. 4｜AddTwo：兩整數相加\n\n來源：[原 PDF 第 4 頁](../../raw/pdfs/1151%20ch8.pdf#page=4)（內文 p. 4） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nAddTwo 接收兩個整數，以 EAX 傳回和：\n```asm\nAddTwo PROC,\n    val1:DWORD, val2:DWORD\n    mov eax,val1\n    add eax,val2\n    ret\nAddTwo ENDP\n```\n\n### 觀念講解\n\n輸入是 val1 與 val2 兩個 DWORD；輸出是 EAX。MOV 先把 val1 的值複製到 EAX，ADD 再將 val2 加入。例如輸入 5 與 6，EAX 依序為 5、11。\n\n這裡沒手寫 PUSH EBP，不代表沒有框架；在本章設定下，MASM 可依 PROC 參數產生進入／退出程式碼。PDF p. 39 會展示展開形式。DWORD 加法保留低 32 位元；若要判斷有號／無號溢位，還須檢查旗標，原例未做。\n\n<a id=\"pdf-p-5\"></a>\n## PDF p. 5｜INVOKE：帶引數呼叫\n\n來源：[原 PDF 第 5 頁](../../raw/pdfs/1151%20ch8.pdf#page=5)（內文 p. 5） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n32 位元模式的 INVOKE 偽指令可取代手動準備多個引數再 CALL 的寫法。\n```asm\nINVOKE procedureName [, argumentList]\n```\n引數串列可省略，項目以逗號分隔。引數可以是立即值與整數運算式、變數名稱、位址及 ADDR 運算式、暫存器名稱。\n\n### 觀念講解\n\nargument 是呼叫端實際提供的資料，parameter 是程序端接收它的名稱。例如 INVOKE AddTwo,5,6 中，5、6 是引數，val1、val2 是參數。\n\nINVOKE 是組譯時的便利語法；MASM 依原型及呼叫慣例安排引數並生成 CALL。它不是 CPU 另有一條能理解任意型別的 INVOKE 指令，亦不會自行替你判斷指標指向的記憶體是否有效。\n\n<a id=\"pdf-p-6\"></a>\n## PDF p. 6｜PROTO：先宣告介面\n\n來源：[原 PDF 第 6 頁](../../raw/pdfs/1151%20ch8.pdf#page=6)（內文 p. 6） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nPROTO 建立程序原型：\n```asm\nlabel PROTO paramList\n```\n原頁說明：64 位元模式不允許這裡的參數串列；每個以 INVOKE 呼叫的程序都要有原型，完整的程序定義也可充當自己的原型。\n\n### 觀念講解\n\n原型告訴 MASM 名稱、參數型別與順序，讓呼叫點不必等到程序實作才知道如何傳參數。只有 PROTO 並不產生函式主體，也不能代替連結時的實作。\n\n如果完整 PROC 定義在呼叫點之前，組譯器已有介面資訊；如果定義在後面或另一個模組，先寫 PROTO。原型與實作必須一致，否則呼叫端與被呼叫端可能對堆疊內容有不同解讀。\n\n<a id=\"pdf-p-7\"></a>\n## PDF p. 7｜PROTO、INVOKE 與實作的位置\n\n來源：[原 PDF 第 7 頁](../../raw/pdfs/1151%20ch8.pdf#page=7)（內文 p. 7） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n典型配置：程序原型放在程式前方，INVOKE 放在程式碼區段，程序實作稍後出現。\n```asm\nMySub PROTO             ; 程序原型\n.code\nINVOKE MySub            ; 呼叫\nMySub PROC              ; 實作\n    ; ...\nMySub ENDP\n```\n\n### 觀念講解\n\n由上到下分清三件事：PROTO 宣告「有這個介面」，INVOKE 是執行時要發生的呼叫，PROC...ENDP 是被執行的主體。此例沒有參數，所以原型與呼叫都不附引數。\n\n這張只是位置示意，省略主程序入口、正常結束及完整主體。若把片段逐字串成可執行流程，不能讓呼叫返回後又直接落入程序本體；完整程式要安排主程序的結束或跳轉。\n\n<a id=\"pdf-p-8\"></a>\n## PDF p. 8｜ArraySum 的指標與長度原型\n\n來源：[原 PDF 第 8 頁](../../raw/pdfs/1151%20ch8.pdf#page=8)（內文 p. 8） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nArraySum 原型列出兩個參數：\n```asm\nArraySum PROTO,\n    ptrArray:PTR DWORD,  ; 指向陣列\n    szArray:DWORD        ; 陣列大小\n```\n\n### 觀念講解\n\nptrArray 是陣列第一個元素的位址；szArray 提供元素數，因為只有指標無法知道陣列長度。PTR DWORD 指出每個元素按 4 bytes 解讀，但指標本身在本章 flat 32 位元模型也是 4 bytes。\n\n若三個 DWORD 位於 A、A+4、A+8，呼叫者傳 A 與 3；實作才知道要讀三次，每次位址加 4。這張只宣告介面，沒有相加流程或實際回傳值的程式。\n\n<a id=\"pdf-p-9\"></a>\n## PDF p. 9｜堆疊框架的建立\n\n來源：[原 PDF 第 9 頁](../../raw/pdfs/1151%20ch8.pdf#page=9)（內文 p. 10） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n堆疊框架（stack frame）也稱活動紀錄（activation record），是為一次程序呼叫保留的堆疊區域，包含返回位址、傳入參數、保存的暫存器與區域變數。\n\n建立步驟：呼叫者先將引數壓入堆疊並呼叫程序；被呼叫者將 EBP 壓入堆疊，再令 EBP=ESP；需要區域變數時，從 ESP 減去固定大小以保留空間。\n\n### 觀念講解\n\n堆疊向較低位址成長，所以 PUSH 會讓 ESP 變小。EBP 固定作為這次呼叫的定位基準，ESP 則可因 PUSH 或區域配置繼續移動。\n\n本章典型框架內，[EBP] 是舊 EBP，[EBP+4] 是返回位址，[EBP+8] 起是參數，負偏移處放區域變數。這個配置由「32 位元近呼叫＋先存 EBP」推得；若省略 frame pointer 或換呼叫慣例，不能直接套用。\n\n<a id=\"pdf-p-10\"></a>\n## PDF p. 10｜堆疊參數與暫存器參數\n\n來源：[原 PDF 第 10 頁](../../raw/pdfs/1151%20ch8.pdf#page=10)（內文 p. 11） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁認為堆疊參數較方便，並比較兩種呼叫方式，問哪種較容易：\n```asm\n; 暫存器介面\npushad\nmov esi,OFFSET array\nmov ecx,LENGTHOF array\nmov ebx,TYPE array\ncall DumpMem\npopad\n\n; 假設採堆疊介面的版本\npush TYPE array\npush LENGTHOF array\npush OFFSET array\ncall DumpMem\n```\n\n### 觀念講解\n\n兩段要交付的資訊相同：陣列起始位址、元素數及每個元素的 bytes 數。左段先保存通用暫存器，再設定 ESI／ECX／EBX；右段把三筆資料壓入堆疊，由程序依位置讀取。\n\n右段比較簡潔的前提，是被呼叫程序真的採這種堆疊介面，並且雙方約定誰清除 12 bytes 的引數。PUSHAD／POPAD 也會保存及還原 EAX，所以不能把這個模板直接套在以 EAX 回傳結果的呼叫上。\n\n### 教學補充／提醒\n\n介面警告：這是「兩種可能介面」的比較，不代表只改呼叫端就能改用原本的同名函式。本教材未取得／執行所用 Irvine32 函式庫的對應實作，不把右段聲稱為可直接替換的已測試程式。\n\n<a id=\"pdf-p-11\"></a>\n## PDF p. 11｜傳值呼叫的步驟\n\n來源：[原 PDF 第 11 頁](../../raw/pdfs/1151%20ch8.pdf#page=11)（內文 p. 12） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n傳值（passing by value）：把引數的值壓入堆疊；原頁建議在保護模式只使用 32 位元值以維持堆疊對齊。接著呼叫程序，有傳回值時從 EAX 接收；若被呼叫者未移除引數，由呼叫者移除。\n\n### 觀念講解\n\n傳值複製的是資料本身。被呼叫者改寫參數副本，並不因此改寫呼叫者原變數；如果值本身是位址，仍可透過該位址修改被指向物。\n\n以兩個 DWORD 為例，參數共占 8 bytes。若 callee 用 RET 8 清除，caller 就不能再 ADD ESP,8；若 callee 只用 RET，caller 便須依約補回。少清或重複清都會破壞 ESP。這裡的 4-byte 建議不等於所有 ABI 的對齊規則。\n\n<a id=\"pdf-p-12\"></a>\n## PDF p. 12｜傳值範例：CALL 前的 5 與 6\n\n來源：[原 PDF 第 12 頁](../../raw/pdfs/1151%20ch8.pdf#page=12)（內文 p. 13） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n資料及呼叫：\n```asm\n.data\nval1 DWORD 5\nval2 DWORD 6\n.code\npush val2\npush val1\ncall AddTwo\n```\nCALL 前的圖由高至低位址為 val2 的值 6、val1 的值 5；ESP 指向 5 所在的頂端。\n\n### 觀念講解\n\n用 S 表示壓引數前的 ESP。PUSH val2 後 ESP=S−4，[S−4]=6；PUSH val1 後 ESP=S−8，[S−8]=5。因為先壓第二個引數，再壓第一個，引數一離返回位址最近。\n\n圖上還沒有返回位址，因為它畫的是 CALL 之前。執行 CALL 才會再占 4 bytes；在 AddTwo 內建立框架後，5 對應 [EBP+8]，6 對應 [EBP+12]。\n\n<a id=\"pdf-p-13\"></a>\n## PDF p. 13｜傳址呼叫的步驟\n\n來源：[原 PDF 第 13 頁](../../raw/pdfs/1151%20ch8.pdf#page=13)（內文 p. 14） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n傳址（passing by reference）：將引數的偏移位址壓入堆疊，再呼叫程序；若有傳回值則從 EAX 接收。若被呼叫者未移除引數，呼叫者須移除。\n\n### 觀念講解\n\n此處「傳址」的機制，是把位址當成引數值傳入。要交換兩個原變數，程序須先取得各位址，再讀寫該位址的內容；只交換堆疊上的指標副本不會交換原資料。\n\n例如 p 指向 val1，MOV ESI,p 取得位址，MOV EAX,[ESI] 才讀到 val1。傳值與傳址在 PUSH 時都會複製某個 32 位元值，差別在這個值被雙方約定解讀成「資料」還是「指標」。\n\n<a id=\"pdf-p-14\"></a>\n## PDF p. 14｜傳址範例：Swap 的兩個位址\n\n來源：[原 PDF 第 14 頁](../../raw/pdfs/1151%20ch8.pdf#page=14)（內文 p. 15） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原資料仍是 val1=5、val2=6，但改傳位址：\n```asm\npush OFFSET val2\npush OFFSET val1\ncall Swap\n```\nCALL 前的示意圖顯示：val2 的 offset 為 00000004，val1 的 offset 為 00000000；ESP 指向 val1 的 offset。\n\n### 觀念講解\n\n這次堆疊不是 6 和 5，而是兩個儲存位置。圖把資料起點簡化成 0，所以相鄰 DWORD 的偏移相差 4；不表示 Windows 實際把變數放在可直接使用的絕對位址 0。\n\n若 val1 在 A，val2 就在 A+4。Swap 須把 [A] 與 [A+4] 的內容互換，結果 val1=6、val2=5。這些寫入是程序實作的責任；CALL 本身不會交換資料。\n\n<a id=\"pdf-p-15\"></a>\n## PDF p. 15｜CALL 之後多出的返回位址\n\n來源：[原 PDF 第 15 頁](../../raw/pdfs/1151%20ch8.pdf#page=15)（內文 p. 16） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nCALL 後的堆疊圖，由高至低位址為：val2 的值或位址、val1 的值或位址、返回位址；ESP 指向返回位址。\n\n### 觀念講解\n\n近 CALL 一方面改變 EIP，使執行轉到程序入口；另一方面先把「CALL 後下一條指令的位置」壓入堆疊，以便 RET 回來。\n\n承接前例，CALL 前 ESP=S−8，CALL 後 ESP=S−12。此時 [ESP] 是返回位址，[ESP+4] 是第一個參數，[ESP+8] 是第二個參數；這還不是 EBP 框架。再 PUSH EBP 之後，參數相對 EBP 的偏移才變成 +8、+12。\n\n<a id=\"pdf-p-16\"></a>\n## PDF p. 16｜RET 與 RET n\n\n來源：[原 PDF 第 16 頁](../../raw/pdfs/1151%20ch8.pdf#page=16)（內文 p. 17） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nRET 從子程序返回：將堆疊頂端彈入指令指標 EIP 或 IP，控制流程轉到該位址。\n```asm\nret\nret n\n```\n選用的 n 表示在載入返回位址後，再把堆疊指標增加 n bytes。\n\n### 觀念講解\n\n在本章 32 位元近返回中，RET 先消耗 4-byte 返回位址。RET 8 另外略過 8 bytes 的引數；總計 ESP 比執行前增加 12。\n\n若目前 ESP 還指著區域變數或未 POP 的暫存器，RET 會把錯誤資料當成返回位址。故順序必須先恢復框架，再 RET；RET n 的 n 是 bytes 數，不是參數個數，也不是包含返回位址的總大小。\n\n<a id=\"pdf-p-17\"></a>\n## PDF p. 17｜以 EBP 固定偏移存取參數\n\n來源：[原 PDF 第 17 頁](../../raw/pdfs/1151%20ch8.pdf#page=17)（內文 p. 18） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁說 C／C++ 函式以相對 EBP 的常數偏移存取堆疊參數，例如 [EBP+8]。EBP 稱為基底指標或框架指標，保存堆疊框架的基底；函式執行期間不改變 EBP，返回前須恢復它原本的值。\n\n### 觀念講解\n\n固定 EBP 的好處是定位穩定：即使 ESP 因配置區域空間或 PUSH 暫存器改變，參數仍在原本的 EBP+8、EBP+12。程序用自己的 EBP 工作，結束時 POP 回呼叫者的 EBP，才能延續上一層框架。\n\n這是使用 frame pointer 的教學模型。最佳化的 C／C++ 編譯結果可以省略 EBP 框架，其他 ABI 也可能用暫存器傳參數，因此「所有 C/C++ 函式都這樣存取」會超出原例適用範圍。\n\n<a id=\"pdf-p-18\"></a>\n## PDF p. 18｜AddTwo：手動基底偏移定址\n\n來源：[原 PDF 第 18 頁](../../raw/pdfs/1151%20ch8.pdf#page=18)（內文 p. 19） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁 AddTwo(5,6) 的程式：\n```asm\nAddTwo PROC\n    push ebp\n    mov ebp,esp\n    mov eax,[ebp+12]\n    add eax,[ebp+8]\n    pop ebp\n    ret 8\n```\n圖中 [EBP] 是舊 EBP，[EBP+4] 是返回位址，[EBP+8]=5，[EBP+12]=6；此時 EBP 與 ESP 相同。\n\n### 觀念講解\n\n先 PUSH EBP 保存舊框架，再 MOV EBP,ESP。讀 [EBP+12] 使 EAX=6，加入 [EBP+8] 的 5，得到 11。這裡把第二參數先讀入仍正確，是因為加法交換律；下一個減法練習不能照抄相同順序。\n\n本例沒有區域變數或額外未還原的 PUSH，所以 POP EBP 前 ESP 仍等於框架基底，可直接取回舊 EBP。RET 8 接著返回並清除兩個 DWORD 引數。\n\n<a id=\"pdf-p-19\"></a>\n## PDF p. 19｜8／16 位元引數的擴充\n\n來源：[原 PDF 第 19 頁](../../raw/pdfs/1151%20ch8.pdf#page=19)（內文 p. 20） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁提醒：不能直接 PUSH 8 位元值；PUSH 16 位元運算元可能造成 page fault 或 ESP 對齊問題。建議先以 MOVZX 將較小引數擴充為 32 位元：\n```asm\n.data\ncharVal BYTE 'x'\n.code\nmovzx eax,charVal\npush eax\ncall Uppercase\n```\n\n### 觀念講解\n\n'x' 的字元碼為 78h。MOVZX 把來源 8 位元值放入 EAX 低位並把高位清零，得到 00000078h；PUSH EAX 按 4 bytes 傳入，維持本章參數槽配置。\n\n原頁的 fault 說法不是必然：PDF p. 45 就示範 PUSH AX 合法地讓 ESP 減 2。問題是混入 2-byte PUSH 後，ESP 不再維持原有 4-byte 邊界，與假設 4-byte 參數槽的介面可能不相容；不能說每次 PUSH AX 都會 fault。\n\n### 教學補充／提醒\n\nMOVZX 適合無號資料／字元。若要把有號 BYTE 的 −1 保持成 32 位元 −1，應使用符號擴充 MOVSX，否則零擴充會把 FFh 解讀成 255。這是依二補數表示補充的適用條件。\n\n<a id=\"pdf-p-20\"></a>\n## PDF p. 20｜練習：Difference(30,14)\n\n來源：[原 PDF 第 20 頁](../../raw/pdfs/1151%20ch8.pdf#page=20)（內文 p. 21） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n建立 Difference 程序，計算第一引數 Val1 減第二引數 Val2：Val1−Val2。\n```asm\npush 14              ; Val2\npush 30              ; Val1\ncall Difference      ; 預期 EAX=16\n```\nCALL 前圖示 ESP 指向 30，其上一格為 14。\n\n### 觀念講解\n\n這題檢查「壓入順序」和「算術順序」是否分得清楚。右至左壓入後，建立標準框架的第一引數在 +8，第二引數在 +12。\n\n代理教學解法（手動框架版本）：\n```asm\nDifference PROC\n    push ebp\n    mov ebp,esp\n    mov eax,[ebp+8]   ; 30\n    sub eax,[ebp+12]  ; 30-14=16\n    pop ebp\n    ret 8\nDifference ENDP\n```\nEAX 先載入被減數，再減去第二參數。若反過來，結果是 −16。此片段為教學推導，未經 MASM 組譯執行。\n\n<a id=\"pdf-p-21\"></a>\n## PDF p. 21｜區域變數：範圍與生命期\n\n來源：[原 PDF 第 21 頁](../../raw/pdfs/1151%20ch8.pdf#page=21)（內文 p. 23） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁說明：只有子程序內的敘述能看見或修改區域變數；子程序結束時，它使用的儲存空間釋放。不同函式可有同名區域變數而不衝突。區域變數對遞迴程序及多個執行緒執行的程序十分重要。\n\n### 觀念講解\n\n同名不衝突，首先是名稱的作用域不同；每次呼叫的儲存位置也可不同。遞迴每深入一次就建立一份新框架，因此每層的 temp 不會直接覆蓋上一層 temp。\n\n「只有程序內可修改」是名稱可見性的簡化說法：如果把區域變數位址傳出去，其他程序仍能在它有效期間透過指標存取它。返回後不可繼續把該指標當成仍有效的區域儲存。區域變數也不保證整個程序就執行緒安全，仍要看共享資料。\n\n<a id=\"pdf-p-22\"></a>\n## PDF p. 22｜手動配置兩個 DWORD 區域變數\n\n來源：[原 PDF 第 22 頁](../../raw/pdfs/1151%20ch8.pdf#page=22)（內文 p. 24） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n明確配置區域變數時，從 ESP 減去所需總大小。原頁配置 locA 與 locB 兩個 32 位元區域變數並初始化：\n```asm\nMySub PROC\n    push ebp\n    mov ebp,esp\n    add esp,-8\n    mov [ebp-4],123456h ; locA\n    mov [ebp-8],0       ; locB\n    ; ...\n```\n\n### 觀念講解\n\n兩個 DWORD 共需 2×4=8 bytes。ADD ESP,−8 與 SUB ESP,8 效果相同，只保留空間，還不會自動清零；後面的 MOV 才分別寫入初值。\n\nEBP−4 和 EBP−8 是各 4-byte 槽的起點。原碼沒有用具名型別或暫存器指明 MOV 的資料寬度，MASM 可能無法判定；可明確寫成 MOV DWORD PTR [EBP-4],123456h 及 MOV DWORD PTR [EBP-8],0。下一頁提供明確寬度的版本。結束時還須 MOV ESP,EBP、POP EBP 再返回。\n\n<a id=\"pdf-p-23\"></a>\n## PDF p. 23｜x=10、y=20 的框架配置\n\n來源：[原 PDF 第 23 頁](../../raw/pdfs/1151%20ch8.pdf#page=23)（內文 p. 25） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n用兩個 DWORD 區域變數表示 int x=10,y=20：\n```asm\nMySub PROC\n    push ebp\n    mov ebp,esp\n    sub esp,8\n    mov DWORD PTR [ebp-4],10\n    mov DWORD PTR [ebp-8],20\n```\n圖由高至低位址：返回位址、保存的 EBP、x=10（EBP−4）、y=20（EBP−8）。\n\n### 觀念講解\n\n如果建立框架後 EBP=B，SUB ESP,8 使 ESP=B−8。x 使用 B−4 至 B−1，y 使用 B−8 至 B−5；兩塊相鄰且不重疊。\n\nDWORD PTR 是對記憶體存取寬度的指定，不是要把立即值變成指標。程式片段只展示進入與初始化，未展示退出；須先把 ESP 還原到 B，才能 POP 到保存的舊 EBP。\n\n<a id=\"pdf-p-24\"></a>\n## PDF p. 24｜LEA：區域變數位址不能用 OFFSET\n\n來源：[原 PDF 第 24 頁](../../raw/pdfs/1151%20ch8.pdf#page=24)（內文 p. 26） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nLEA 取得有效位址；OFFSET 運算子只能提供組譯／連結可決定的固定偏移。要取得堆疊參數或區域變數的位址，需要 LEA。原例：\n```asm\nCopyString PROC, count:DWORD\nLOCAL temp[20]:BYTE\nmov edi,OFFSET count  ; 無效運算元\nmov esi,OFFSET temp   ; 無效運算元\n; 應該用哪條指令？\n```\n\n### 觀念講解\n\ncount 與 temp 的實際位置由當次呼叫的 EBP 決定，每次呼叫可不同；OFFSET 無法把目前執行時的 EBP 算進固定常數。\n\n教學替代是 LEA EDI,count 與 LEA ESI,temp，由 MASM 將具名項目解析成框架相對定址。count 的位址與 count 的值不同：若要取數值用 MOV EDI,count；若要讓另一程序透過指標存取這個參數槽才取位址。\n\n<a id=\"pdf-p-25\"></a>\n## PDF p. 25｜LEA 範例：EBP−8 的位址\n\n來源：[原 PDF 第 25 頁](../../raw/pdfs/1151%20ch8.pdf#page=25)（內文 p. 27） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n假設區域變數在 [EBP−8]，要把該變數的位址放入 ESI。不能使用：\n```asm\nmov esi,OFFSET [ebp-8] ; 錯誤\n```\n應使用：\n```asm\nlea esi,[ebp-8]\n```\n\n### 觀念講解\n\n假設 EBP=00100020h，LEA 計算 00100020h−8=00100018h，將此位址放入 ESI；它不會讀取 00100018h 裡面儲存的數值。\n\n若該位置存 20，MOV ESI,[EBP-8] 會得到 20，而 LEA ESI,[EBP-8] 得到 00100018h。這正是「值」與「位置」的差別；方括號在 LEA 中提供有效位址運算式，不表示本指令會解參考讀值。\n\n<a id=\"pdf-p-26\"></a>\n## PDF p. 26｜ENTER：建立框架的指令\n\n來源：[原 PDF 第 26 頁](../../raw/pdfs/1151%20ch8.pdf#page=26)（內文 p. 28） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nENTER 為被呼叫程序建立堆疊框架：保存 EBP、設定框架基底、保留區域變數空間。\n```asm\nMySub PROC\n    enter 8,0\n```\n在本例等價於：\n```asm\npush ebp\nmov ebp,esp\nsub esp,8\n```\n\n### 觀念講解\n\n第一個引數 8 指保留 8 bytes，第二個 0 表示此例不建立巢狀語言框架鏈。若執行前 ESP=S，保存 EBP 後為 S−4；令 EBP=S−4；再保留 8 bytes，ESP=S−12。\n\nENTER 是 CPU 指令，LOCAL／PROC 則是組譯器偽指令。這裡的等價展開只針對第二運算元為 0 的簡單情況；不要把所有 ENTER 的語意都縮成固定三行。\n\n<a id=\"pdf-p-27\"></a>\n## PDF p. 27｜LEAVE：回收框架後再 RET\n\n來源：[原 PDF 第 27 頁](../../raw/pdfs/1151%20ch8.pdf#page=27)（內文 p. 29） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nLEAVE 結束程序的堆疊框架。原頁程序先 ENTER 8,0，中間執行主體，然後 LEAVE、RET。\n```asm\nenter 8,0\n; ...\nleave\nret\n```\n本例 LEAVE 的等價操作：\n```asm\nmov esp,ebp           ; 釋放區域空間\npop ebp\n```\n\n### 觀念講解\n\nMOV ESP,EBP 把堆疊頂端直接移回保存舊 EBP 的位置，所以不必逐一 POP 區域變數。POP EBP 再把上一層框架基底恢復，這時 ESP 才指向返回位址，RET 因而能正確返回。\n\n回收空間不是擦除內容；只是這段堆疊不再由本次呼叫占有。如果程序另外保存了 ESI／EBX 等必須還原的暫存器，應按它們實際存放的配置先還原；不能用 LEAVE 丟棄應恢復的值。\n\n<a id=\"pdf-p-28\"></a>\n## PDF p. 28｜LOCAL：宣告有型別的區域變數\n\n來源：[原 PDF 第 28 頁](../../raw/pdfs/1151%20ch8.pdf#page=28)（內文 p. 30） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nLOCAL 宣告區域變數串列，緊接在 PROC 後方，每個變數指定型別。\n```asm\nLOCAL varlist\n\nMySub PROC\nLOCAL var1:BYTE, var2:WORD, var3:SDWORD\n```\n\n### 觀念講解\n\nLOCAL 讓組譯器替你安排堆疊位置，主體中可直接用 var1、var2、var3，不必手算所有 EBP 偏移。BYTE 是 1 byte、WORD 是 2 bytes、SDWORD 是有號 4 bytes；實際配置還可能包含對齊空間，不能只把 1+2+4 當成所有版本必然生成的框架大小。\n\n宣告只保留儲存空間，未給初值。若後續要累計 sum，必須先初始化，不能假設新區域變數從 0 開始。\n\n<a id=\"pdf-p-29\"></a>\n## PDF p. 29｜LOCAL temp 的 MASM 展開\n\n來源：[原 PDF 第 29 頁](../../raw/pdfs/1151%20ch8.pdf#page=29)（內文 p. 31） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原始宣告：\n```asm\nExample1 PROC\nLOCAL temp:DWORD\n    ; ...\n    ret\nExample1 ENDP\n```\n原頁展示 MASM 生成的形式：\n```asm\nExample1 PROC\n    push ebp\n    mov ebp,esp\n    add esp,0FFFFFFFCh ; ESP 加 -4\n    ; ...\n    mov esp,ebp\n    pop ebp\n    ret\nExample1 ENDP\n```\n\n### 觀念講解\n\n32 位元二補數中 FFFFFFFCh 代表 −4，所以 ADD ESP,FFFFFFFCh 為 temp 保留 4 bytes。temp 在本例對應 [EBP−4]，而不是全域資料區的固定位置。\n\n返回前先釋放區域空間、恢復舊 EBP，再取回返回位址。這張是「宣告與生成指令」的對照；不要把自動框架與同一份手寫框架一起重複放進同個帶參數程序，否則會多保存一次 EBP、偏移也會不同。\n\n<a id=\"pdf-p-30\"></a>\n## PDF p. 30｜Example1 的框架圖\n\n來源：[原 PDF 第 30 頁](../../raw/pdfs/1151%20ch8.pdf#page=30)（內文 p. 33） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nExample1 的堆疊框架圖：返回位址位於 EBP+4；舊 EBP 位於 EBP；區域 DWORD temp 位於 EBP−4。配置完成後 ESP 指向 temp，也就是 EBP−4。\n\n### 觀念講解\n\n每格 4 bytes。EBP 保持基準不動，ESP 因 temp 的存在向下移一格；因此 EBP 和 ESP 不是永遠相同。\n\n先辨認正方向：EBP+4 往較高位址找到返回位址，EBP−4 往較低位址找到區域變數。如果此時再 PUSH EAX，ESP 會變 EBP−8，但 temp 仍在 EBP−4。這就是用 EBP 而非不斷變動的 ESP 定位區域資料的原因。\n\n<a id=\"pdf-p-31\"></a>\n## PDF p. 31｜再看 INVOKE 與 32 位元限制\n\n來源：[原 PDF 第 31 頁](../../raw/pdfs/1151%20ch8.pdf#page=31)（內文 p. 34） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n本頁重述 INVOKE：32 位元模式下，可用它準備多個引數並呼叫程序。\n```asm\nINVOKE procedureName [, argumentList]\n```\n引數可為立即值／整數運算式、變數名稱、位址／ADDR 運算式或暫存器名稱；原頁再次標示不適用於 64-bit 模式。\n\n### 觀念講解\n\n現在已看過框架，可把高階寫法與堆疊連起來：INVOKE 在呼叫端安排引數，PROC 在程序端為參數命名，兩者依同一原型與呼叫慣例配合。\n\n在本章常見的右至左堆疊傳參數模型中，INVOKE AddTwo,5,6 可概念展開為 PUSH 6、PUSH 5、CALL AddTwo；其他呼叫慣例或引數型別不一定照此固定三行。Microsoft 官方 INVOKE 文件明列它是 32-bit MASM 用法。\n\n<a id=\"pdf-p-32\"></a>\n## PDF p. 32｜INVOKE 的四種引數\n\n來源：[原 PDF 第 32 頁](../../raw/pdfs/1151%20ch8.pdf#page=32)（內文 p. 35） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁資料與範例：\n```asm\n.data\nbyteVal BYTE 10\nwordVal WORD 1000h\n.code\nINVOKE Sub1,byteVal,wordVal ; 直接運算元\nINVOKE Sub2,ADDR byteVal   ; 變數位址\nINVOKE Sub3,eax,(10 * 20)  ; 暫存器、整數運算式\nINVOKE Sub4,[ebx]         ; 原頁稱位址運算式／間接運算元\n```\n\n### 觀念講解\n\nSub1 收到兩個變數的值；Sub2 收到 byteVal 的位址，兩者不能混淆。Sub3 的第二個引數是組譯時可計算的 200，第一個則取呼叫當時 EAX 的內容。\n\n最後一行要釐清：普通 [EBX] 是讀 EBX 所指記憶體的內容，不等於傳 EBX 這個位址，也不等於 ADDR。只有該內容本身是一個有效指標且原型期望指標時，才構成傳入該指標；原型還須足以判定資料大小。這些範例省略各 Sub 的 PROTO，不能據此假設任意型別組合都可直接組譯。\n\n<a id=\"pdf-p-33\"></a>\n## PDF p. 33｜ADDR：依記憶體模型取得指標\n\n來源：[原 PDF 第 33 頁](../../raw/pdfs/1151%20ch8.pdf#page=33)（內文 p. 36） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nADDR 在 32 位元 INVOKE 呼叫中可用來傳遞指標引數，依程式的記憶體模型回傳 near 或 far 指標。原頁對照：Small 模型為 16-bit offset；Large 模型為 32-bit segment/offset；Flat 模型為 32-bit offset。旁註不適用於 64-bit 模式。\n```asm\n.data\nmyWord WORD ?\n.code\nINVOKE mySub,ADDR myWord\n```\n\n### 觀念講解\n\n在本章 flat 32 位元環境，ADDR myWord 提供 myWord 的 32 位元位址；myWord 自己只有 2 bytes，這不影響指標的 4-byte 大小。\n\nSmall／Large 是原頁帶入的舊式分段記憶體模型對照；Large 的「32 位元」指 segment 與 offset 的組合寬度，不能當成 flat 32-bit 線性位址的同義詞。ADDR 是 INVOKE 的組譯器運算子；不是執行時的一條 CPU ADDR 指令。\n\n<a id=\"pdf-p-34\"></a>\n## PDF p. 34｜INVOKE Swap：先自行展開\n\n來源：[原 PDF 第 34 頁](../../raw/pdfs/1151%20ch8.pdf#page=34)（內文 p. 37） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁宣告 20 個未初始化 DWORD，並要求對照 INVOKE 與相對應程式碼：\n```asm\n.data\nArray DWORD 20 DUP(?)\n.code\n; ...\nINVOKE Swap, ADDR Arrary, ADDR [Array+4]\n```\n原頁「Corresponding Code」下方以青色方塊遮住答案；下一頁揭露。\n\n### 觀念講解\n\n先判斷要交換哪兩個物件：第一個是 Array[0]，第二個是 Array[1]。DWORD 每格 4 bytes，因此第二元素的位址是 Array+4，不是 Array+1。\n\n教學推導：若第一參數為第一元素位址、第二參數為第二元素位址，採右至左傳入時要先壓 Array+4，再壓 Array。原頁 Arrary 是拼字錯誤，應為已宣告的 Array；保留原文並在下一頁給出修正形式。20 DUP(?) 只配置空間，未給可交換的確定初值。\n\n<a id=\"pdf-p-35\"></a>\n## PDF p. 35｜INVOKE Swap：展開答案與拼字勘誤\n\n來源：[原 PDF 第 35 頁](../../raw/pdfs/1151%20ch8.pdf#page=35)（內文 p. 38） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n本頁與前頁同題，原呼叫仍寫成：\n```asm\nINVOKE Swap, ADDR Arrary, ADDR [Array+4]\n```\n這次揭露對應程式碼：\n```asm\npush OFFSET Array+4\npush OFFSET Array\ncall Swap\n```\n資料宣告仍為 Array DWORD 20 DUP(?)。\n\n### 觀念講解\n\n勘誤：宣告的是 Array，呼叫中的 Arrary 應改為 Array。修正後概念寫法為 INVOKE Swap,ADDR Array,ADDR [Array+4]。\n\n兩次 PUSH 都傳位址，不讀取陣列元素；原型可寫 Swap PROTO,pValX:PTR DWORD,pValY:PTR DWORD。交換過程才經由這兩個指標讀寫元素。如果陣列未先初始化，雖可談位址配置，卻不能宣稱交換後有哪兩個固定數值。\n\n<a id=\"pdf-p-36\"></a>\n## PDF p. 36｜再看 PROC 參數宣告\n\n來源：[原 PDF 第 36 頁](../../raw/pdfs/1151%20ch8.pdf#page=36)（內文 p. 39） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n本頁重述 PROC：宣告程序並可附具名參數串列；各參數以逗號分隔，形式為 paramName:type。型別可為 BYTE、SBYTE、WORD 等標準型別，或指向這些型別的指標。原頁列 label PROC paramList，並附 64-bit 不適用警語。\n\n### 觀念講解\n\n前面已把參數看成框架中的位置，這裡可重新理解型別：名稱供人閱讀，型別讓 MASM 知道讀取幾 bytes，以及 INVOKE 應如何檢查引數。\n\n例如 pValX:PTR DWORD 的參數槽保存位址；若寫 MOV EAX,pValX，是載入指標，不是直接讀取它指向的 DWORD。仍須再以 [EAX] 等間接定址解參考。PROC 這個指令本身也有 x64 形式，限制應讀成本章參數配置的限制。\n\n<a id=\"pdf-p-37\"></a>\n## PDF p. 37｜再看參數串列與逗號\n\n來源：[原 PDF 第 37 頁](../../raw/pdfs/1151%20ch8.pdf#page=37)（內文 p. 40） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n參數串列可放一行或多行；另起行時格式為：\n```asm\nlabel PROC,\n    param1:type1,\n    param2:type2,\n    ; ...\n    paramN:typeN\n```\n原頁另列同一行以逗號分隔的方式，並以箭頭指出 PROC 後的逗號不可省略。\n\n### 觀念講解\n\n這是 PDF p. 3 的重複內容，仍保留實體頁碼。現在可以用它檢查後面 FillArray：fillVal:BYTE 後還有 arraySize:DWORD，所以兩者之間需要逗號。\n\n程序宣告最後一個參數後不必為了換行再加逗號。不要把逗號放入名稱或型別，因為它是參數間的分隔符，而不是型別的一部分。\n\n<a id=\"pdf-p-38\"></a>\n## PDF p. 38｜再看具名 AddTwo\n\n來源：[原 PDF 第 38 頁](../../raw/pdfs/1151%20ch8.pdf#page=38)（內文 p. 41） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nAddTwo 接收兩整數，以 EAX 回傳和。本頁重列：\n```asm\nAddTwo PROC,\n    val1:DWORD, val2:DWORD\n    mov eax,val1\n    add eax,val2\n    ret\nAddTwo ENDP\n```\n\n### 觀念講解\n\n把本頁與下一頁成對讀：這裡用 val1／val2，下一頁會改寫成 [EBP+8]／[EBP+0Ch]。因此具名參數讓原始碼更易讀，底層仍是框架相對存取。\n\n程序承諾 EAX 帶回結果；輸入 5、6 時，MOV 取 5，ADD 得 11，退出框架不應把 EAX 用 POPAD 或其他還原操作覆蓋回舊值。\n\n<a id=\"pdf-p-39\"></a>\n## PDF p. 39｜具名參數如何變成 EBP 偏移\n\n來源：[原 PDF 第 39 頁](../../raw/pdfs/1151%20ch8.pdf#page=39)（內文 p. 42） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nMASM 將 AddTwo 的參數名稱轉成相對 EBP 的偏移；原頁展開：\n```asm\nAddTwo PROC\n    push ebp\n    mov ebp,esp\n    mov eax,DWORD PTR [ebp+8]\n    add eax,DWORD PTR [ebp+0Ch]\n    leave\n    ret 8\nAddTwo ENDP\n```\n\n### 觀念講解\n\n0Ch 就是十進位 12。第一個參數的位移 +8，來自舊 EBP 的 4 bytes 與返回位址的 4 bytes；第二個再往上 4 bytes，所以是 +12。\n\nLEAVE 恢復舊框架，RET 8 返回並清除兩個 DWORD 引數。這是講義在其 MASM 設定下展示的展開結果，不表示不同語言慣例、prologue 選項或版本必定逐字生成同樣指令。\n\n<a id=\"pdf-p-40\"></a>\n## PDF p. 40｜Swap 與 ReadFile 的介面\n\n來源：[原 PDF 第 40 頁](../../raw/pdfs/1151%20ch8.pdf#page=40)（內文 p. 43） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁提供兩個程序範本：\n```asm\nSwap PROC,\n    pValX:PTR DWORD,\n    pValY:PTR DWORD\n    ; ...\nSwap ENDP\n\nReadFile PROC,\n    pBuffer:PTR BYTE\nLOCAL fileHandle:DWORD\n    ; ...\nReadFile ENDP\n```\n\n### 觀念講解\n\nSwap 的兩個指標讓程序能改寫兩個 DWORD；ReadFile 的 pBuffer 是外部傳入的位址，而 fileHandle 是這次呼叫自己使用的區域 DWORD。\n\n兩者在框架的位置性質不同：參數位於正偏移，區域變數通常在負偏移。PTR BYTE 表示緩衝區元素按 byte 解讀，不提供緩衝區長度或讀入上限。原頁只展示介面，省略實作及退出流程；此 ReadFile 名稱也不能據此認定為完整 Windows API 宣告。\n\n<a id=\"pdf-p-41\"></a>\n## PDF p. 41｜FillArray：補上寫入與位址遞增\n\n來源：[原 PDF 第 41 頁](../../raw/pdfs/1151%20ch8.pdf#page=41)（內文 p. 44） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nFillArray 接收 byte 陣列指標、要複製到每個元素的單一 byte 值，以及陣列大小。原頁程式骨架：\n```asm\nFillArray PROC,\n    pArray:PTR BYTE, fillVal:BYTE\n    arraySize:DWORD\n    mov ecx,arraySize\n    mov esi,pArray\n    mov al,fillVal\nL1: mov ; 運算元以青色遮住\n    inc ; 運算元以青色遮住\n    loop L1\n    ret\nFillArray ENDP\n```\n完整揭露在下一頁；原頁 fillVal:BYTE 後漏逗號。\n\n### 觀念講解\n\n先依三個準備步驟推理：ECX 是剩餘次數，ESI 是目前元素位址，AL 是填入值。迴圈每次應把 AL 寫到 [ESI]，再將 ESI 加 1，才能移到下一個 BYTE。\n\n教學填空為 MOV [ESI],AL 與 INC ESI。LOOP 會先讓 ECX 減 1，再於非零時跳回；因此本骨架需要 arraySize>0。若長度為 0，卻先進入主體，就會寫入不應寫的元素，之後還可能發生極長迴圈。\n\n<a id=\"pdf-p-42\"></a>\n## PDF p. 42｜FillArray：完整流程與邊界修正\n\n來源：[原 PDF 第 42 頁](../../raw/pdfs/1151%20ch8.pdf#page=42)（內文 p. 45） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n本頁揭露 FillArray 的迴圈：\n```asm\nFillArray PROC,\n    pArray:PTR BYTE, fillVal:BYTE\n    arraySize:DWORD\n    mov ecx,arraySize\n    mov esi,pArray\n    mov al,fillVal\nL1: mov [esi],al\n    inc esi\n    loop L1\n    ret\nFillArray ENDP\n```\n輸入及用途與前頁相同：將指定 byte 填入整個 byte 陣列。原碼仍漏了 fillVal 後的逗號。\n\n### 觀念講解\n\n以 pArray=A、fillVal=7、arraySize=3 為例：初始 ECX=3、ESI=A、AL=7；三輪分別寫 [A]、[A+1]、[A+2]，每輪 ESI 加 1，ECX 依序變 2、1、0，最後不跳回。\n\n教學修正分三件事：①在 fillVal:BYTE 後補逗號；②在第一次寫入前加 JECXZ Done，讓 0 長度直接退出；③若介面要求保存 ESI，使用 USES ESI 或正確的保存／還原。Done 應放在 RET 前。傳入非零長度時，也須確保緩衝區有至少該長度可寫；原例未做界限檢查。\n\n<a id=\"pdf-p-43\"></a>\n## PDF p. 43｜讀值還是取位址：先預測結果\n\n來源：[原 PDF 第 43 頁](../../raw/pdfs/1151%20ch8.pdf#page=43)（內文 p. 46） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁陣列與指令：\n```asm\n.data\nEx1Array SDWORD 10,-20,30,50,40,-2\n.code\nmain PROC\n    mov eax,Ex1Array+12\n    mov ebx,[Ex1Array+12]\n    mov ecx,OFFSET Ex1Array+12\n    lea edx,Ex1Array+12\n    call DumpRegs\n    ; ...\n```\n下方輸出在本頁以青色方塊遮住；下一頁揭露結果。\n\n### 觀念講解\n\n每個 SDWORD 占 4 bytes，所以 +12 位移到索引 3 的第四元素 50。MASM 的具型別資料標號可直接表示記憶體運算元，因此前兩條 MOV 都讀取該元素的值；是否有方括號不是唯一判斷依據。\n\nOFFSET 與 LEA 則都在此例取得第四元素的位址。先預測 EAX=EBX=50、ECX=EDX=該位址，再看下一頁。這個 MASM 語法不能直接類比其他組譯器的所有同形寫法。\n\n<a id=\"pdf-p-44\"></a>\n## PDF p. 44｜讀值與取位址：暫存器結果\n\n來源：[原 PDF 第 44 頁](../../raw/pdfs/1151%20ch8.pdf#page=44)（內文 p. 47） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原碼與前頁相同。註解換算 50=16×3+2=00000032h。DumpRegs 圖顯示：\n```text\nEAX=00000032  EBX=00000032\nECX=00404010  EDX=00404010\nESI=00000000  EDI=00000000\nEBP=0018FF90  ESP=0018FF88\nEIP=0040101B  EFL=00000246\nCF=0 SF=0 ZF=1 OF=0 AF=0 PF=1\n```\n前兩個是第四元素的值，後兩個是該次範例執行的位址。\n\n### 觀念講解\n\n50 除 16 得商 3、餘 2，故十六進位為 32h。EAX／EBX 都是 00000032h；ECX／EDX 的 00404010h 則指向該資料。反推本次陣列起點為 00404010h−0Ch=00404004h。\n\n位址只是這張圖的執行結果，重新連結或載入後可能不同。這段 MOV 與 LEA 不負責計算 50−某值，故不可把畫面上的 ZF=1 等旗標硬解成「剛做了比較」；旗標可能來自先前狀態。\n\n<a id=\"pdf-p-45\"></a>\n## PDF p. 45｜TestStack：追蹤不同寬度的 PUSH\n\n來源：[原 PDF 第 45 頁](../../raw/pdfs/1151%20ch8.pdf#page=45)（內文 p. 48） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n原頁程序及觀察值（十六進位）：\n```asm\nTestStack PROC,\n    arg1:WORD,\n    arg2:BYTE\nLOCAL temp[10]:BYTE\n    call DumpRegs         ; ESP=0019FF58, EBP=0019FF64\n    mov ax,arg1\n    push eax\n    call DumpRegs         ; ESP=0019FF54\n    push ax\n    call DumpRegs         ; ESP=0019FF52\n    push WORD PTR 10\n    call DumpRegs         ; ESP=0019FF50\n    push 10\n    call DumpRegs         ; ESP=0019FF4C\n    ret 8\nTestStack ENDP\n```\n圖另記「呼叫 TestStack 前 ESP=0019FF74」。\n\n### 觀念講解\n\n由 FF74 到框架 EBP=FF64 共減 10h=16 bytes，可與兩個各占 4 bytes 的引數槽、返回位址、舊 EBP 對應。LOCAL temp[10]:BYTE 後 ESP=FF58，比 EBP 再低 0Ch=12 bytes：圖展示了局部配置含對齊的情況，不只配置 10 bytes。\n\n接著從 FF58 起，PUSH EAX 減 4，PUSH AX 減 2，PUSH WORD PTR 10 減 2，PUSH 10 在本模式減 4，得到 FF54、FF52、FF50、FF4C。MOV AX,arg1 只更新 EAX 的低 16 位，所以隨後 PUSH EAX 的高 16 位不可假定為零。\n\nRET 8 清的是兩個引數槽，不是前面測試 PUSH 的 12 bytes。原頁依賴 MASM 自動 epilogue 恢復 ESP／EBP；如果改成完全手寫框架而直接 RET 8，會從錯誤位置取返回位址。圖中的 DumpRegs 數值視為觀察呼叫者狀態，並非要額外永久累計每個 CALL 的返回位址。\n\n<a id=\"pdf-p-46\"></a>\n## PDF p. 46｜多模組程式的建置流程\n\n來源：[原 PDF 第 46 頁](../../raw/pdfs/1151%20ch8.pdf#page=46)（內文 p. 49） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n多模組程式將原始程式分成不同 ASM 檔案。每個 ASM 檔案（模組）各自組譯為 OBJ；同一程式的全部 OBJ 再由 link 工具連結為單一 EXE。\n\n### 觀念講解\n\n分清兩個階段：組譯器處理單個模組內的指令與符號，產生機器碼及待解析的外部符號；連結器把各模組放在一起，解析跨模組的名稱與位址。\n\n所以 PROTO 能讓呼叫端知道介面，卻不能憑空補出程序的機器碼。若組譯成功但找不到外部函式實作，仍會在連結階段失敗。流程圖為「main.asm→main.obj」及「helper.asm→helper.obj」，兩者再一起連到程式 EXE。\n\n<a id=\"pdf-p-47\"></a>\n## PDF p. 47｜多模組的優點與封裝條件\n\n來源：[原 PDF 第 47 頁](../../raw/pdfs/1151%20ch8.pdf#page=47)（內文 p. 50） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n大型程式分成來源模組後較容易撰寫、維護、除錯。修改一行程式時，通常只需重新組譯它所屬的模組；已組譯模組的連結所需時間較少。模組可集中邏輯相關的程式與資料。\n\n原頁把封裝說明為：程序與變數在模組內自動隱藏，除非將它們宣告為 public。\n\n### 觀念講解\n\n拆分讓每個模組有可理解的責任，例如一個處理輸入、一個加總、一個顯示。修改加總實作時，若介面不變，其餘模組的原始碼可能不必重組。\n\n但原頁的 public 說法需要條件：MASM 的程序可見性也受預設與選項影響，不能保證每個 PROC 自動 private。應檢查實際 PUBLIC／PRIVATE 及匯出符號設定。若共同 include 的介面變更，所有依賴它的模組也可能都要重組；「只重組一個」不是所有變更都成立。\n\n<a id=\"pdf-p-48\"></a>\n## PDF p. 48｜建立多模組程式的步驟\n\n來源：[原 PDF 第 48 頁](../../raw/pdfs/1151%20ch8.pdf#page=48)（內文 p. 51） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n基本步驟：建立主模組；為每個程序或一組相關程序建立獨立來源模組；建立 include 檔，放入外部程序（跨模組呼叫者）的原型；使用 INCLUDE 讓各模組都取得這些原型。\n\n### 觀念講解\n\n先定介面，再分工實作。例如 main 呼叫 ArraySum，把 ArraySum 的 PROTO 放進共同 sum.inc；main.asm 與實作模組都 INCLUDE 它，讓型別與順序有共同依據。\n\nINCLUDE 是組譯前／組譯時引入宣告內容，不會把另一個 OBJ 自動連入 EXE。仍要組譯實作模組並在連結時提供它；宣告、實作、可見性與連結輸入四件事都要配合。\n\n<a id=\"pdf-p-49\"></a>\n## PDF p. 49｜sum.inc：三個外部程序的原型\n\n來源：[原 PDF 第 49 頁](../../raw/pdfs/1151%20ch8.pdf#page=49)（內文 p. 52） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\nsum.inc 包含不在 Irvine32 函式庫內的外部函式原型：\n```asm\nINCLUDE Irvine32.inc\nPromptForIntegers PROTO,\n    ptrPrompt:PTR BYTE,  ; 提示字串\n    ptrArray:PTR DWORD,  ; 陣列\n    arraySize:DWORD     ; 陣列大小\nArraySum PROTO,\n    ptrArray:PTR DWORD,  ; 陣列\n    count:DWORD         ; 元素數\nDisplaySum PROTO,\n    ptrPrompt:PTR BYTE,  ; 提示字串\n    theSum:DWORD        ; 陣列總和\n```\n\n### 觀念講解\n\n三個介面串成資料流：PromptForIntegers 用提示字串引導輸入，把數值寫入陣列；ArraySum 根據陣列位址和長度求和；DisplaySum 接收提示及已算出的和。\n\n前兩者都需要指標加長度，第三者接收的是總和值，不是指向總和的指標。此頁只有原型，未展示完整實作或所有回傳約定；不可僅憑原型就說已執行並得到結果。也不要以為 INCLUDE Irvine32.inc 已包含這三個自訂程序。\n\n<a id=\"pdf-p-50\"></a>\n## PDF p. 50｜作業三：CountMatches 規格\n\n來源：[原 PDF 第 50 頁](../../raw/pdfs/1151%20ch8.pdf#page=50)（內文 p. 53） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n撰寫 CountMatches：接收兩個有號雙字陣列的指標，以及第三個參數表示兩陣列共同長度。對每個第一陣列的元素 xᵢ，若同位置 yᵢ 相等，計數加一，最後用 EAX 回傳相等元素的數量。\n\n另寫測試程式，呼叫 CountMatches 並傳入兩組不同的陣列配對。用 INVOKE 傳遞堆疊參數，為 CountMatches 建立 PROTO；程序改動的暫存器，除了 EAX 之外都須保存並還原。\n\n加分題（額外 2 分）：計算所有相符元素，不限相同位置。\n\n### 觀念講解\n\n基本題是逐位置比較，不是搜尋另一陣列任意位置。教學介面可寫 CountMatches PROTO,pX:PTR SDWORD,pY:PTR SDWORD,count:DWORD。\n\n流程：EAX=0；若 count=0 直接返回；用兩個指標各讀一個 DWORD，以 CMP 判斷相等，相等才增加 EAX；兩指標各加 4，重複 count 次。CMP 不能直接同時使用兩個一般記憶體運算元，因此先把其中一個元素載入暫存器。\n\n保存 ESI／EDI／ECX／EDX 等實際改動的暫存器；不要把 EAX 的結果還原掉。加分題可用外層取 xᵢ、內層搜尋 yⱼ；下一頁的「無重複元素」假設讓匹配數有明確集合交集解讀。\n\n<a id=\"pdf-p-51\"></a>\n## PDF p. 51｜作業三：基本 2 筆、加分 5 筆\n\n來源：[原 PDF 第 51 頁](../../raw/pdfs/1151%20ch8.pdf#page=51)（內文 p. 54） · [Wiki 來源](../../wiki/sources/src-20261105-assembly-ch8.md)\n\n### 中文翻譯\n\n基本題對下列陣列回報 2 筆匹配：\n```asm\narray1 SDWORD 10,5,4,-6,2,11,12\narray2 SDWORD 10,5,3,1,4,2,-6\n```\n加分題對相同兩陣列回報 5 筆匹配。原頁特別假設陣列中沒有重複元素。\n\n### 觀念講解\n\n基本題依序比較：(10,10) 相等、(5,5) 相等，接著 (4,3)、(−6,1)、(2,4)、(11,2)、(12,−6) 都不相等，所以 EAX=2。\n\n加分題允許跨位置，兩陣列共同元素為 10、5、4、−6、2，共 5 個。11 與 12 不在第二陣列，因此不計。若不允許位置不同的匹配，就不能把結果算成 5。\n\n代理測試設計另包含空陣列、全相等、完全不相等與負數；演算法模型測試及 MASM 原生執行的狀態分別記錄在交付報告。若允許重複，須先決定是交集不同值數、成功找到的元素數，還是所有相等配對數，原題沒有替重複情況下定義。\n\n## 參考文獻\n\n### 已使用並納入 Wiki\n\n- [組合語言第八章｜原始 PDF](../../raw/pdfs/1151%20ch8.pdf)：主要來源 · PDF pp. 1–51 · Kip R. Irvine · 2015 版投影片與課堂增補混編。\n- [Microsoft Learn｜INVOKE](https://learn.microsoft.com/en-us/cpp/assembler/masm/invoke?view=msvc-170)：2026-11-05 有限查證：正文與語法；32-bit MASM 的適用範圍。\n- [Microsoft Learn｜PROC](https://learn.microsoft.com/en-us/cpp/assembler/masm/proc?view=msvc-170)：2026-11-05 有限查證：語法與 Remarks；含 x64 FRAME，未使用其完整例程。\n- [Microsoft Learn｜PROTO](https://learn.microsoft.com/en-us/cpp/assembler/masm/proto?view=msvc-170)：2026-11-05 有限查證：定義、語法與參數；原型與語言慣例。\n- [Microsoft Learn｜LOCAL](https://learn.microsoft.com/en-us/cpp/assembler/masm/local-masm?view=msvc-170)：2026-11-05 有限查證：程序內 LOCAL 的語法與生命期。\n- [Microsoft Learn｜OPTION](https://learn.microsoft.com/en-us/cpp/assembler/masm/option-masm?view=msvc-170)：2026-11-05 有限查證：選項列表中的 PROC／PROLOGUE／EPILOGUE。\n- [Microsoft Learn｜PUBLIC](https://learn.microsoft.com/en-us/cpp/assembler/masm/public-masm?view=msvc-170)：2026-11-05 有限查證：定義與語法；跨模組可見性。\n- [Microsoft Learn｜__stdcall](https://learn.microsoft.com/en-us/cpp/cpp/stdcall?view=msvc-170)：僅正文及 Remarks 表：右至左、callee 清引數；未匯入範例。\n- [Microsoft Learn｜x64 calling convention](https://learn.microsoft.com/en-us/cpp/build/x64-calling-convention?view=msvc-170)：僅 defaults、alignment、parameter passing：釐清本章與 Windows x64 範圍；其餘未使用。\n\n[外部查證的實際範圍](../../wiki/sources/web-20261105-microsoft-masm-procedures.md)。外部連結需連網。\n\n### 延伸閱讀／待匯入\n\n目前無另列候選；未閱讀的官方手冊段落不作正文證據。\n\n## 進度與限制\n\n51 頁全部閱讀，翻譯與講解完整對應；來源勘誤與未原生執行的限制見上方說明及 [交付紀錄](../../teaching/assembly-language/chapter-8/delivery.md)。\n", "references": [{"title": "組合語言第八章｜原始 PDF", "url": "raw/pdfs/1151 ch8.pdf", "detail": "主要來源 · PDF pp. 1–51 · Kip R. Irvine · 2015 版投影片與課堂增補混編"}, {"title": "Microsoft Learn｜INVOKE", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/invoke?view=msvc-170", "detail": "2026-11-05 有限查證：正文與語法；32-bit MASM 的適用範圍"}, {"title": "Microsoft Learn｜PROC", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/proc?view=msvc-170", "detail": "2026-11-05 有限查證：語法與 Remarks；含 x64 FRAME，未使用其完整例程"}, {"title": "Microsoft Learn｜PROTO", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/proto?view=msvc-170", "detail": "2026-11-05 有限查證：定義、語法與參數；原型與語言慣例"}, {"title": "Microsoft Learn｜LOCAL", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/local-masm?view=msvc-170", "detail": "2026-11-05 有限查證：程序內 LOCAL 的語法與生命期"}, {"title": "Microsoft Learn｜OPTION", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/option-masm?view=msvc-170", "detail": "2026-11-05 有限查證：選項列表中的 PROC／PROLOGUE／EPILOGUE"}, {"title": "Microsoft Learn｜PUBLIC", "url": "https://learn.microsoft.com/en-us/cpp/assembler/masm/public-masm?view=msvc-170", "detail": "2026-11-05 有限查證：定義與語法；跨模組可見性"}, {"title": "Microsoft Learn｜__stdcall", "url": "https://learn.microsoft.com/en-us/cpp/cpp/stdcall?view=msvc-170", "detail": "僅正文及 Remarks 表：右至左、callee 清引數；未匯入範例"}, {"title": "Microsoft Learn｜x64 calling convention", "url": "https://learn.microsoft.com/en-us/cpp/build/x64-calling-convention?view=msvc-170", "detail": "僅 defaults、alignment、parameter passing：釐清本章與 Windows x64 範圍；其餘未使用"}]};
